}

/* Arabic = RTL + sidebar right */
html[dir="rtl"] .reference-admin{
  direction:rtl !important;
  padding-right:260px !important;
  padding-left:0 !important;
}
html[dir="rtl"] .reference-sidebar{
  right:0 !important;
  left:auto !important;
