html[dir="rtl"] .reference-brand,
html[dir="rtl"] .reference-market-card,
html[dir="rtl"] .reference-nav button,
html[dir="rtl"] .reference-sidebar-foot,
html[dir="rtl"] .reference-admin-header,
html[dir="rtl"] .reference-page-heading,
html[dir="rtl"] .reference-panel-top,
html[dir="rtl"] .reference-order-tools,
html[dir="rtl"] .reference-orders-grid,
html[dir="rtl"] .reference-admin .admin-order{
