  .ai-kpis{
    grid-template-columns:repeat(3,minmax(0,1fr));
  }

  .ai-main-grid{
    grid-template-columns:1fr;
  }

  .ai-guardrails{
    position:static;
  }

  .ai-telemetry-grid{
    grid-template-columns:1fr 1fr;
  }

  .ai-telemetry-grid>.ai-card:last-child{
    grid-column:1/-1;
  }
}

/* Small tablet */
@media(max-width:900px){
  .ai-hero{
    flex-direction:column;
    align-items:flex-start;
  }

  .ai-hero-actions{
    width:100%;
    min-width:0;
    justify-items:stretch;
  }

  .ai-clock{
    width:100%;
    min-width:0;
  }

  .ai-kpis{
    grid-template-columns:1fr 1fr;
  }

  .ai-telemetry-grid{
    grid-template-columns:1fr;
  }

  .ai-telemetry-grid>.ai-card:last-child{
    grid-column:auto;
  }
}

/* Mobile */
@media(max-width:760px){
  .ai-hero{
    border-radius:15px;
    padding:17px;
    margin-bottom:10px;
  }

  .ai-hero h1{
    font-size:24px;
  }

  .ai-hero p{
    font-size:8px;
  }

  .ai-kpis{
    grid-template-columns:1fr 1fr;
    gap:8px;
  }

  .ai-kpis article{
    min-height:108px;
    padding:11px;
  }

  .ai-kpis strong{
    font-size:19px;
  }

  .ai-card{
    border-radius:14px;
  }

  .ai-card>header{
    padding:12px;
  }

  .ai-case-grid{
    grid-template-columns:1fr;
  }

  .ai-sensor-grid{
    grid-template-columns:1fr 1fr 1fr;
  }

  .ai-simulator form{
    grid-template-columns:1fr;
  }

  .ai-primary-btn{
    width:100%;
  }

  .ai-sim-result{
    grid-template-columns:1fr;
  }

  .ai-sim-result p{
    grid-column:auto;
  }
}

@media(max-width:520px){
  .ai-kpis{
    grid-template-columns:1fr;
  }

  .ai-sensor-grid{
    grid-template-columns:1fr;
  }

  .ai-hero-actions{
    gap:8px;
  }
}


/* =====================================================================
   KABSH NAJD — WHATSAPP INBOX v22
   3-column operational workspace inspired by supplied reference design.
   ===================================================================== */

.wa-topbar{
  background:#fff;
  border:1px solid #dfe7e2;
  border-radius:17px 17px 0 0;
  padding:15px 17px;
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:18px;
  box-shadow:0 8px 24px rgba(11,74,59,.045);
}

.wa-title-group{
  display:flex;
  align-items:flex-start;
  gap:11px;
  min-width:0;
}

.wa-title-icon{
  width:38px;
  height:38px;
  border-radius:11px;
  display:grid;
  place-items:center;
  background:#e8f4ef;
  color:#0b4a3b;
  flex:0 0 38px;
}

.wa-title-icon .admin-svg-icon{
  width:20px !important;
  height:20px !important;
  min-width:20px !important;
  max-width:20px !important;
}

.wa-title-group>div{
  min-width:0;
}

.wa-heading-line{
  display:flex;
  align-items:center;
  flex-wrap:wrap;
  gap:8px;
}

.wa-heading-line h1{
  margin:0;
  font-size:21px;
  line-height:1.22;
  color:#123b30;
}

.wa-api-chip{
  display:inline-flex;
  align-items:center;
  gap:6px;
  border-radius:999px;
  background:#e9f6f0;
  color:#2a6b54;
  padding:5px 8px;
  font-size:6px;
  font-weight:800;
}

.wa-api-chip i{
  width:7px;
  height:7px;
  border-radius:50%;
  background:#35bd7f;
  box-shadow:0 0 0 3px rgba(53,189,127,.12);
}

.wa-title-group p{
  margin:5px 0 0;
  color:#5f6f68;
  font-size:7px;
  line-height:1.6;
}

.wa-mode-actions{
  display:flex;
  align-items:center;
  gap:8px;
  flex-wrap:wrap;
  justify-content:flex-end;
}

.wa-mode-toggle{
  display:flex;
  align-items:center;
  gap:4px;
  padding:4px;
  border-radius:11px;
  background:#f2f5f3;
  border:1px solid #e2e8e5;
}

.wa-mode-toggle button{
  min-height:32px;
  padding:0 10px;
  border-radius:8px;
  display:flex;
  align-items:center;
  gap:6px;
  color:#62756c;
  font-size:7px;
  font-weight:800;
}

.wa-mode-toggle button.active{
  background:#0b4a3b;
  color:#fff;
  box-shadow:0 4px 12px rgba(11,74,59,.14);
}

.wa-mode-toggle .admin-svg-icon{
  width:15px !important;
  height:15px !important;
  min-width:15px !important;
  max-width:15px !important;
}

.wa-icon-button{
  width:34px;
  height:34px;
  border-radius:9px;
  border:1px solid #dce5e0;
  background:#fff;
  color:#24483b;
  display:grid;
  place-items:center;
  position:relative;
}

.wa-icon-button i{
  position:absolute;
  width:6px;
  height:6px;
  border-radius:50%;
  background:#d7a43e;
  top:5px;
  inset-inline-end:5px;
}

.wa-new-chat{
  min-height:34px;
  border-radius:9px;
  padding:0 11px;
  background:#0b4a3b;
  color:#fff;
  display:flex;
  align-items:center;
  gap:6px;
  font-size:7px;
  font-weight:800;
}

/* Main 3-column layout */
.wa-grid{
  min-height:690px;
  display:grid;
  grid-template-columns:280px minmax(0,1fr) 285px;
  background:#fff;
  border:1px solid #dfe7e2;
  border-top:0;
  border-radius:0 0 17px 17px;
  overflow:hidden;
  box-shadow:0 14px 38px rgba(11,74,59,.065);
}

.wa-conversations{
  border-inline-end:1px solid #e5ebe8;
  background:#fbfcfb;
  min-width:0;
  display:flex;
  flex-direction:column;
}

.wa-list-tools{
  padding:12px;
  border-bottom:1px solid #e6ece9;
  background:#fff;
}

.wa-list-tools>label{
  height:38px;
  display:flex;
  align-items:center;
  gap:7px;
  border:1px solid #dce5e0;
  border-radius:10px;
  padding:0 10px;
  background:#fbfcfb;
}

.wa-list-tools>label input{
  width:100%;
  min-width:0;
  border:0;
  outline:0;
  background:transparent;
  color:#29483c;
  font-size:7px;
}

.wa-filter-row{
  display:flex;
  gap:5px;
  margin-top:8px;
  overflow:auto;
  scrollbar-width:none;
}

.wa-filter-row::-webkit-scrollbar{display:none}

.wa-filter-row button{
  min-height:29px;
  padding:0 8px;
  border-radius:8px;
  background:#fff;
  border:1px solid #e1e8e4;
  color:#61746b;
  white-space:nowrap;
  font-size:6px;
  display:flex;
  align-items:center;
  gap:5px;
}

.wa-filter-row button b{
  min-width:18px;
  height:18px;
  border-radius:999px;
  display:grid;
  place-items:center;
  background:#eef3f0;
  color:#50675c;
  font-size:6px;
}

.wa-filter-row button.active{
  background:#0b4a3b;
  color:#fff;
  border-color:#0b4a3b;
}

.wa-filter-row button.active b{
  background:#c99b43;
  color:#17362d;
}

.wa-chat-list{
  flex:1;
  overflow:auto;
  padding:7px;
}

.wa-chat-item{
  width:100%;
  border-radius:11px;
  padding:9px;
  display:grid;
  grid-template-columns:40px minmax(0,1fr);
  gap:9px;
  text-align:start;
  color:#203c32;
  border:1px solid transparent;
  background:transparent;
  margin-bottom:4px;
}

.wa-chat-item:hover{
  background:#f3f7f5;
}

.wa-chat-item.active{
  background:#fff;
  border-color:#dfe7e2;
  box-shadow:0 5px 14px rgba(11,74,59,.05);
}

.wa-avatar{
  width:38px;
  height:38px;
  min-width:38px;
  border-radius:50%;
  display:grid;
  place-items:center;
  background:linear-gradient(145deg,#dfece6,#f3f7f5);
  color:#0b4a3b;
  font-size:13px;
  font-weight:800;
  position:relative;
}

.wa-avatar i{
  position:absolute;
  width:8px;
  height:8px;
  border-radius:50%;
  background:#39c282;
  border:2px solid #fff;
  bottom:0;
  inset-inline-end:0;
}

.wa-chat-copy{
  min-width:0;
  display:grid;
  gap:4px;
}

.wa-chat-name{
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:8px;
}

.wa-chat-name b{
  overflow:hidden;
  white-space:nowrap;
  text-overflow:ellipsis;
  font-size:8px;
}

.wa-chat-name small{
  flex:0 0 auto;
  color:#87928c;
  font-size:6px;
}

.wa-preview{
  color:#6f7f77;
  font-size:6px;
  line-height:1.45;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.wa-tags{
  display:flex;
  gap:4px;
  flex-wrap:wrap;
}

.wa-tags em{
  min-height:19px;
  border-radius:999px;
  padding:0 6px;
  background:#eef3f0;
  color:#60736a;
  display:flex;
  align-items:center;
  gap:4px;
  font-size:5px;
  font-style:normal;
  font-weight:700;
}

.wa-tags em.ai{
  background:#e8f5ef;
  color:#1f6d4f;
}

.wa-tags em.human{
  background:#f4ead2;
  color:#7c6028;
}

.wa-tags .admin-svg-icon{
  width:10px !important;
  height:10px !important;
  min-width:10px !important;
  max-width:10px !important;
}

/* Center chat */
.wa-active-chat{
  min-width:0;
  display:flex;
  flex-direction:column;
  background:#f3f0e8;
}

.wa-chat-header{
  min-height:64px;
  padding:10px 13px;
  background:#fff;
  border-bottom:1px solid #e3e9e6;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
}

.wa-profile{
  display:flex;
  align-items:center;
  gap:9px;
  min-width:0;
}

.wa-profile>div{
  min-width:0;
}

.wa-profile>div>div{
  display:flex;
  align-items:center;
  gap:5px;
}

.wa-profile h2{
  margin:0;
  font-size:12px;
  color:#173d31;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.wa-profile p{
  margin:3px 0 0;
  color:#77867e;
  font-size:6px;
}

.wa-profile .admin-svg-icon{
  color:#2b7d60;
  width:14px !important;
  height:14px !important;
  min-width:14px !important;
  max-width:14px !important;
}

.wa-chat-header-actions{
  display:flex;
  gap:5px;
}

.wa-chat-header-actions button,
.wa-chat-header-actions a{
  width:31px;
  height:31px;
  border-radius:8px;
  border:1px solid #dfe6e2;
  background:#fff;
  color:#315044;
  display:grid;
  place-items:center;
}

.wa-message-history{
  flex:1;
  overflow:auto;
  padding:15px 18px 12px;
  background:
    radial-gradient(circle at 20% 10%,rgba(255,255,255,.45),transparent 26%),
    linear-gradient(180deg,#f7f4ed,#f0ede5);
}

.wa-day-label{
  width:max-content;
  margin:0 auto 12px;
  padding:4px 8px;
  border-radius:999px;
  background:#e2e6e3;
  color:#687a71;
  font-size:6px;
}

.wa-message-row{
  display:flex;
  margin:7px 0;
}

.wa-message-row.in{
  justify-content:flex-start;
}

.wa-message-row.out{
  justify-content:flex-end;
}

.wa-bubble{
  max-width:72%;
  padding:8px 10px 6px;
  border-radius:12px;
  background:#fff;
  color:#29473c;
  box-shadow:0 2px 8px rgba(0,0,0,.035);
  border:1px solid #e4e9e6;
}

.wa-message-row.out .wa-bubble{
  background:#dff2e8;
  border-color:#d0e8dc;
}

.wa-bubble.bot{
  background:#e8f1ff;
  border-color:#dbe7f6;
}

.wa-bubble>small{
  display:flex;
  align-items:center;
  gap:4px;
  color:#4d6c85;
  font-size:5px;
  font-weight:800;
  margin-bottom:4px;
}

.wa-bubble>small .admin-svg-icon{
  width:10px !important;
  height:10px !important;
  min-width:10px !important;
  max-width:10px !important;
}

.wa-bubble p{
  margin:0;
  font-size:7px;
  line-height:1.65;
}

.wa-bubble time{
  display:block;
  margin-top:4px;
  text-align:end;
  color:#5f6f68;
  font-size:5px;
}

/* Product card inside chat */
.wa-product-card{
  width:min(420px,84%);
  border-radius:13px;
  overflow:hidden;
  background:#fff;
  border:1px solid #dfe6e2;
  box-shadow:0 7px 20px rgba(11,74,59,.07);
}

.wa-product-media{
  height:145px;
  position:relative;
  overflow:hidden;
  background:#edf2ef;
}

.wa-product-media img{
  width:100%;
  height:100%;
  object-fit:cover;
  display:block;
}

.wa-product-media span{
  position:absolute;
  top:8px;
  inset-inline-start:8px;
  border-radius:999px;
  background:rgba(255,255,255,.9);
  color:#0b4a3b;
  padding:4px 7px;
  font-size:5px;
  font-weight:800;
}

.wa-product-body{
  padding:10px;
}

.wa-product-body>div:first-child{
  display:flex;
  justify-content:space-between;
  gap:8px;
  align-items:flex-start;
}

.wa-product-body h3{
  margin:0;
  color:#163d31;
  font-size:10px;
}

.wa-product-body b{
  color:#0b4a3b;
  font-size:10px;
  white-space:nowrap;
}

.wa-product-body p{
  margin:5px 0 7px;
  color:#728079;
  font-size:6px;
}

.wa-product-meta{
  display:flex;
  flex-wrap:wrap;
  gap:5px;
}

.wa-product-meta span{
  border-radius:999px;
  background:#f1f5f3;
  color:#60736a;
  padding:4px 6px;
  font-size:5px;
}

.wa-quick-replies{
  display:flex;
  flex-wrap:wrap;
  justify-content:flex-end;
  gap:5px;
  margin-top:10px;
}

.wa-quick-replies button{
  min-height:28px;
  border-radius:999px;
  padding:0 9px;
  background:#fff;
  border:1px solid #d7e1dc;
  color:#355247;
  font-size:6px;
}

.wa-quick-replies button:hover{
  background:#e8f4ef;
  border-color:#cfe4da;
}

.wa-composer{
  min-height:62px;
  padding:9px 11px;
  background:#fff;
  border-top:1px solid #e2e8e5;
  display:grid;
  grid-template-columns:34px minmax(0,1fr) 36px;
  gap:7px;
  align-items:center;
}

.wa-composer>button:not(.wa-send){
  width:34px;
  height:34px;
  border-radius:9px;
  border:1px solid #dce4df;
  display:grid;
  place-items:center;
  color:#486157;
}

.wa-composer textarea{
  min-height:38px;
  max-height:100px;
  resize:none;
  border:1px solid #dce4df;
  border-radius:10px;
  padding:9px 10px;
  outline:0;
  font-size:7px;
  color:#29483c;
  background:#fbfcfb;
}

.wa-send{
  width:36px;
  height:36px;
  border-radius:10px;
  background:#0b4a3b;
  color:#fff;
  display:grid;
  place-items:center;
}

/* Right context panel */
.wa-context{
  border-inline-start:1px solid #e5ebe8;
  background:#fbfcfb;
  padding:10px;
  overflow:auto;
}

.wa-context-card{
  background:#fff;
  border:1px solid #e0e7e3;
  border-radius:12px;
  padding:11px;
  margin-bottom:9px;
}

.wa-context-title{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:7px;
  padding-bottom:8px;
  border-bottom:1px solid #edf1ef;
}

.wa-context-title>span{
  display:flex;
  align-items:center;
  gap:5px;
  color:#24483b;
  font-size:7px;
  font-weight:800;
}

.wa-context-title>b,
.wa-context-title>small{
  border-radius:999px;
  padding:4px 6px;
  background:#e8f5ef;
  color:#226e51;
  font-size:5px;
}

.wa-customer-id{
  display:flex;
  align-items:center;
  gap:8px;
  margin:10px 0;
}

.wa-customer-id h3{
  margin:0;
  color:#173d31;
  font-size:10px;
}

.wa-customer-id p{
  margin:3px 0 0;
  color:#7a8881;
  font-size:6px;
}

.wa-mini-stats{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:7px;
  margin:8px 0 10px;
}

.wa-mini-stats>div{
  padding:8px;
  border-radius:9px;
  background:#f5f8f6;
  border:1px solid #e6ece9;
}

.wa-mini-stats small{
  display:block;
  color:#7d8a83;
  font-size:5px;
  margin-bottom:4px;
}

.wa-mini-stats b{
  color:#0b4a3b;
  font-size:9px;
}

.wa-context dl{
  margin:0;
}

.wa-context dl>div{
  display:flex;
  justify-content:space-between;
  gap:8px;
  padding:7px 0;
  border-top:1px solid #edf1ef;
}

.wa-context dt{
  color:#5f6f68;
  font-size:6px;
}

.wa-context dd{
  margin:0;
  color:#29483c;
  font-size:6px;
  font-weight:800;
  text-align:end;
}

.wa-linked-order>div:first-child{
  display:flex;
  justify-content:space-between;
  gap:7px;
  align-items:flex-start;
  margin:10px 0 7px;
}

.wa-linked-order h3{
  margin:0;
  color:#193e32;
  font-size:9px;
}

.wa-linked-order b{
  color:#0b4a3b;
  font-size:9px;
  white-space:nowrap;
}

.wa-linked-order p{
  margin:6px 0;
  display:flex;
  align-items:center;
  gap:5px;
  color:#667970;
  font-size:6px;
}

.wa-linked-order p strong{
  color:#24483b;
}

.wa-progress{
  margin-top:10px;
}

.wa-progress>div{
  display:flex;
  justify-content:space-between;
  gap:8px;
  color:#64776e;
  font-size:6px;
}

.wa-progress i{
  display:block;
  height:7px;
  margin-top:5px;
  border-radius:999px;
  background:#edf2ef;
  overflow:hidden;
}

.wa-progress u{
  display:block;
  height:100%;
  border-radius:inherit;
  background:linear-gradient(90deg,#0b4a3b,#c99b43);
  text-decoration:none;
}

.wa-ops-title{
  margin:0 0 8px;
  color:#173d31;
  font-size:9px;
}

.wa-context-card>button,
.wa-open-real{
  width:100%;
  min-height:35px;
  border-radius:9px;
  margin-top:5px;
  padding:0 9px;
  display:flex;
  align-items:center;
  gap:7px;
  border:1px solid #dfe7e2;
  background:#fff;
  color:#335247;
  font-size:6px;
  text-align:start;
}

.wa-context-card>button:hover{
  background:#f4f8f6;
}

.wa-open-real{
  background:#0b4a3b;
  border-color:#0b4a3b;
  color:#fff;
  text-decoration:none;
}

/* Direction */
html[dir="ltr"] .wa-topbar,
html[dir="ltr"] .wa-grid,
html[dir="ltr"] .wa-chat-item,
html[dir="ltr"] .wa-active-chat,
html[dir="ltr"] .wa-context{
  direction:ltr;
  text-align:left;
}

html[dir="rtl"] .wa-topbar,
html[dir="rtl"] .wa-grid,
html[dir="rtl"] .wa-chat-item,
html[dir="rtl"] .wa-active-chat,
html[dir="rtl"] .wa-context{
  direction:rtl;
  text-align:right;
}

/* Responsive */
@media(max-width:1250px){
  .wa-grid{
    grid-template-columns:240px minmax(0,1fr) 240px;
  }
}

@media(max-width:1050px){
  .wa-grid{
    grid-template-columns:230px minmax(0,1fr);
  }
  .wa-context{
    display:none;
  }
}

@media(max-width:820px){
  .wa-topbar{
    align-items:flex-start;
    flex-direction:column;
  }
  .wa-mode-actions{
    width:100%;
