.mkt-coupon-table{
  padding:12px 14px 0;
  overflow:auto;
}

.mkt-coupon-head,
.mkt-coupon-row{
  min-width:900px;
  display:grid;
  grid-template-columns:1.5fr 1fr .65fr .7fr .9fr .9fr .75fr .7fr;
  gap:8px;
  align-items:center;
}

.mkt-coupon-head{
  min-height:39px;
  padding:0 10px;
  border-radius:10px;
  background:#eef1fb;
  color:#687970;
  font-size:6px;
  font-weight:800;
}

.mkt-coupon-row{
  min-height:58px;
  padding:8px 10px;
  border-bottom:1px solid #edf1ef;
  color:#365147;
  font-size:7px;
}

.mkt-coupon-row b{
  color:#173e32;
  font-size:7px;
}

.mkt-coupon-row code{
  border-radius:6px;
  background:#eef1fb;
  color:#3b4c64;
  padding:4px 6px;
  font-size:6px;
}

.mkt-coupon-row em{
  display:inline-flex;
  border-radius:999px;
  padding:5px 7px;
  font-size:6px;
  font-style:normal;
  font-weight:800;
}

.mkt-coupon-row em.active{
  background:#4ce6ad;
  color:#0f4f3b;
}

.mkt-coupon-row em.review{
  background:#ffd98f;
  color:#79571c;
}

.mkt-coupon-row button{
  min-height:28px;
  border-radius:8px;
  padding:0 8px;
  background:#eef3f0;
  color:#355247;
  font-size:6px;
}

.mkt-coupons>footer{
  margin:12px 14px 14px;
  padding:11px 12px;
  border-radius:11px;
  background:#eef1fb;
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:12px;
}

.mkt-coupons>footer small{
  display:block;
  color:#718078;
  font-size:6px;
  margin-bottom:3px;
}

.mkt-coupons>footer b{
  color:#173e32;
  font-size:12px;
}

.mkt-coupons>footer button{
  min-height:31px;
  border-radius:8px;
  padding:0 10px;
  background:#0b4a3b;
  color:#fff;
  font-size:6px;
  font-weight:800;
}

/* Marketing modals */
.mkt-dialog{
  width:min(560px,calc(100vw - 28px));
  border:0;
  border-radius:18px;
  padding:0;
  background:#fff;
  box-shadow:0 26px 76px rgba(13,62,48,.22);
}

.mkt-dialog::backdrop{
  background:rgba(7,37,29,.5);
  backdrop-filter:blur(4px);
}

.mkt-dialog>.close{
  position:absolute;
  top:12px;
  inset-inline-end:12px;
  width:34px;
  height:34px;
  border-radius:9px;
  background:#fff;
  border:1px solid #dce4df;
  z-index:2;
}

.mkt-modal{
  padding:23px;
}

.mkt-modal>small{
  display:block;
  color:#9a7838;
  font-size:7px;
  font-weight:800;
  letter-spacing:.7px;
}

.mkt-modal h2{
  margin:6px 0 14px;
  color:#173e32;
  font-size:20px;
}

.mkt-modal form{
  display:grid;
  gap:10px;
}

.mkt-modal label{
  display:grid;
  gap:5px;
  color:#405b50;
  font-size:7px;
  font-weight:800;
}

.mkt-modal input,
.mkt-modal select{
  min-height:40px;
  border:1px solid #dbe4df;
  border-radius:9px;
  background:#fbfcfb;
  padding:0 10px;
  color:#173e32;
  font-size:8px;
}

.mkt-modal .checkout-cta{
  min-height:41px;
  border-radius:10px;
  background:#0b4a3b;
  color:#fff;
  font-size:8px;
  font-weight:800;
}

/* RTL / LTR */
html[dir="ltr"] .mkt-hero,
html[dir="ltr"] .mkt-section,
html[dir="ltr"] .mkt-ai-studio,
html[dir="ltr"] .mkt-dialog{
  direction:ltr;
  text-align:left;
}

html[dir="rtl"] .mkt-hero,
html[dir="rtl"] .mkt-section,
html[dir="rtl"] .mkt-ai-studio,
html[dir="rtl"] .mkt-dialog{
  direction:rtl;
  text-align:right;
}

/* Responsive */
@media(max-width:1200px){
  .mkt-kpis{
    grid-template-columns:repeat(3,minmax(0,1fr));
  }
  .mkt-campaign-grid{
    grid-template-columns:1fr 1fr;
  }
}

@media(max-width:980px){
  .mkt-hero{
    flex-direction:column;
  }
  .mkt-hero-actions{
    width:100%;
    min-width:0;
    justify-content:flex-start;
  }
  .mkt-ai-grid{
    grid-template-columns:1fr;
  }
}

@media(max-width:760px){
  .reference-admin-content:has(.mkt-hero){
    border-radius:0;
  }
  .mkt-hero{
    border-radius:14px;
    padding:15px;
  }
  .mkt-hero h1{
    font-size:23px;
  }
  .mkt-hero-actions{
    display:grid;
    grid-template-columns:1fr;
  }
  .mkt-hero-actions button{
    justify-content:center;
  }
  .mkt-kpis{
    grid-template-columns:1fr 1fr;
    gap:8px;
  }
  .mkt-campaign-grid{
    grid-template-columns:1fr;
  }
  .mkt-section>header,
  .mkt-ai-studio>header{
    align-items:flex-start;
    flex-direction:column;
  }
  .mkt-section>header>button{
    width:100%;
    justify-content:center;
  }
  .mkt-ai-studio>header>span{
    align-self:flex-start;
  }
  .mkt-creative-media img{
    height:180px;
  }
  .mkt-coupons>footer{
    align-items:flex-start;
    flex-direction:column;
  }
  .mkt-coupons>footer button{
    width:100%;
  }
}

@media(max-width:520px){
  .mkt-kpis{
    grid-template-columns:1fr;
  }
  .mkt-copy-card>div{
    align-items:flex-start;
    flex-direction:column;
  }
  .mkt-card-actions{
    flex-direction:column;
  }
}


/* =====================================================================
   KABSH NAJD — USERS & GOVERNANCE MODULE v33
   Reference-driven styling for governance / RBAC workspace
   ===================================================================== */

body:has(.gov-hero){
  background:#f4f5fb;
}

.reference-admin-content:has(.gov-hero){
  background:#f4f5fb;
  border-radius:18px;
}

/* Top security banner */
.gov-security-bar{
  min-height:42px;
  border-radius:11px;
  background:#0b4a3b;
  color:#fff;
  padding:0 13px;
  margin-bottom:13px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  box-shadow:0 7px 18px rgba(11,74,59,.10);
}

.gov-security-bar>span{
  display:flex;
  align-items:center;
  gap:8px;
  font-size:7px;
  color:#e5f1ed;
  line-height:1.4;
}

.gov-security-bar i{
  width:8px;
  height:8px;
  border-radius:50%;
  background:#40df9d;
  box-shadow:0 0 0 4px rgba(64,223,157,.12);
  flex:0 0 8px;
}

.gov-security-bar>b{
  border-radius:999px;
  background:rgba(255,255,255,.09);
  border:1px solid rgba(255,255,255,.13);
  padding:5px 8px;
  font-size:6px;
  letter-spacing:.4px;
  white-space:nowrap;
}

/* Hero */
.gov-hero{
  background:#fff;
  border:1px solid #e5e8ef;
  border-radius:17px;
  padding:19px 21px;
  display:flex;
  justify-content:space-between;
  align-items:flex-start;
  gap:18px;
  margin-bottom:13px;
  box-shadow:0 8px 22px rgba(27,42,37,.04);
}

.gov-kicker{
  display:flex;
  align-items:center;
  gap:7px;
  color:#8d6d2d;
  font-size:7px;
  font-weight:800;
  margin-bottom:7px;
  flex-wrap:wrap;
}

.gov-kicker>.admin-svg-icon{
  width:26px !important;
  height:26px !important;
  min-width:26px !important;
  max-width:26px !important;
  border-radius:8px;
  padding:6px;
  box-sizing:border-box;
  background:#eef2ff;
  color:#0b4a3b;
}

.gov-hero h1{
  margin:0 0 7px;
  color:#153d31;
  font-size:27px;
  line-height:1.2;
}

.gov-hero p{
  margin:0;
  color:#74827a;
  font-size:8px;
  line-height:1.75;
  max-width:780px;
}

.gov-hero-actions{
  display:flex;
  gap:7px;
  flex-wrap:wrap;
  justify-content:flex-end;
}

.gov-hero-actions button{
  min-height:36px;
  border-radius:9px;
  padding:0 11px;
  border:1px solid #dce5e0;
  background:#eef2ff;
  color:#2d4c41;
  display:flex;
  align-items:center;
  gap:6px;
  font-size:7px;
  font-weight:800;
}

.gov-hero-actions button:first-child{
  background:#0b4a3b;
  color:#fff;
  border-color:#0b4a3b;
}

/* KPIs */
.gov-kpis{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:10px;
  margin-bottom:13px;
}

.gov-kpis article{
  min-height:120px;
  background:#fff;
  border:1px solid #e3e7ee;
  border-radius:14px;
  padding:14px;
  display:flex;
  align-items:flex-start;
  gap:10px;
  box-shadow:0 7px 18px rgba(27,42,37,.035);
  position:relative;
  overflow:hidden;
}

.gov-kpis article::after{
  content:"";
  position:absolute;
  inset-inline-start:0;
  top:0;
  bottom:0;
  width:4px;
  background:#0b4a3b;
}

.gov-kpis article:nth-child(2)::after{background:#37d79c}
.gov-kpis article:nth-child(3)::after{background:#d6a542}
.gov-kpis article:nth-child(4)::after{background:#1f2730}

.gov-kpis article>.admin-svg-icon{
  width:31px !important;
  height:31px !important;
  min-width:31px !important;
  max-width:31px !important;
  border-radius:9px;
  padding:7px;
  box-sizing:border-box;
  background:#eef2ff;
  color:#0b4a3b;
}

.gov-kpis small{
  display:block;
  color:#728178;
  font-size:6px;
  margin-bottom:8px;
}

.gov-kpis strong{
  display:block;
  color:#153d31;
  font-size:24px;
  line-height:1;
  margin-bottom:6px;
}

.gov-kpis span{
  display:block;
  color:#65776e;
  font-size:6px;
  line-height:1.45;
}

/* Tabs */
.gov-tabs{
  background:#fff;
  border:1px solid #e4e8ef;
  border-radius:12px;
  padding:5px;
  display:flex;
  gap:5px;
  overflow:auto;
  margin-bottom:12px;
  scrollbar-width:none;
}

.gov-tabs::-webkit-scrollbar{display:none}

.gov-tabs button{
  min-height:36px;
  border-radius:9px;
  padding:0 11px;
  display:flex;
  align-items:center;
  gap:6px;
  color:#667970;
  background:transparent;
  white-space:nowrap;
  font-size:7px;
  font-weight:800;
}

.gov-tabs button.active{
  background:#eef2ff;
  color:#183f33;
  box-shadow:inset 0 0 0 1px #dde3ef;
}

.gov-tabs button>.admin-svg-icon{
  width:15px !important;
  height:15px !important;
  min-width:15px !important;
  max-width:15px !important;
}

.gov-tabs button>b{
  min-width:20px;
  height:20px;
  border-radius:999px;
  display:grid;
  place-items:center;
  background:#0b4a3b;
  color:#fff;
  font-size:6px;
}

/* Search + filters */
.gov-toolbar{
  background:#fff;
  border:1px solid #e4e8ef;
  border-radius:13px;
  padding:12px;
  margin-bottom:12px;
  display:grid;
  grid-template-columns:minmax(250px,1.35fr) minmax(0,1fr);
  gap:10px;
}

.gov-search,
.gov-filters label{
  min-height:39px;
  border:1px solid #dce4df;
  border-radius:9px;
  background:#fbfcff;
  display:flex;
  align-items:center;
  gap:7px;
  padding:0 10px;
}

.gov-search input{
  width:100%;
  min-width:0;
  border:0;
  outline:0;
  background:transparent;
  color:#29483c;
  font-size:7px;
}

.gov-filters{
  display:grid;
  grid-template-columns:1.2fr 1.2fr 1fr 38px;
  gap:6px;
}

.gov-filters select{
  width:100%;
  min-width:0;
  border:0;
  background:transparent;
  color:#29483c;
  outline:none;
  font-size:7px;
}

.gov-filters button{
  width:38px;
  height:39px;
  border-radius:9px;
  border:1px solid #dce4df;
  background:#eef2ff;
  color:#29483c;
  display:grid;
  place-items:center;
}

/* Registry table */
.gov-registry{
  background:#fff;
  border:1px solid #e4e8ef;
  border-radius:15px;
  overflow:hidden;
  margin-bottom:14px;
  box-shadow:0 8px 22px rgba(27,42,37,.035);
}

.gov-registry>header{
  min-height:63px;
  padding:13px 15px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  border-bottom:1px solid #e8ebf1;
}

.gov-registry>header>div{
  display:flex;
  align-items:center;
  gap:8px;
  flex-wrap:wrap;
}

.gov-registry>header>div>span{
  width:8px;
  height:8px;
  border-radius:50%;
  background:#32d792;
  box-shadow:0 0 0 4px rgba(50,215,146,.10);
}

.gov-registry h2{
  margin:0;
  color:#153d31;
  font-size:16px;
}

.gov-registry header small{
  color:#7c8982;
  font-size:6px;
}

.gov-registry header button{
  min-height:33px;
  border-radius:8px;
  padding:0 9px;
  background:#0b4a3b;
  color:#fff;
  display:flex;
  align-items:center;
  gap:6px;
  font-size:6px;
  font-weight:800;
}

.gov-table-wrap{
  overflow:auto;
}

.gov-registry table{
  width:100%;
  min-width:1050px;
  border-collapse:collapse;
}

.gov-registry thead{
  background:#eef2ff;
}

.gov-registry th{
  padding:10px 11px;
  color:#5f6f68;
  font-size:6px;
  text-align:start;
  font-weight:800;
}

.gov-registry td{
  padding:11px;
  border-bottom:1px solid #edf0f4;
  vertical-align:middle;
  color:#344f45;
  font-size:7px;
}

.gov-registry tbody tr:hover{
  background:#fbfcff;
}

/* user cell */
.gov-user{
  display:grid;
  grid-template-columns:38px minmax(0,1fr);
  gap:8px;
  align-items:center;
  min-width:220px;
}

.gov-user>span{
  width:36px;
  height:36px;
  border-radius:50%;
  display:grid;
  place-items:center;
  background:#0b4a3b;
  color:#fff;
  font-size:9px;
  font-weight:800;
}

.gov-user b,
.gov-role b,
.gov-session b{
  display:block;
  color:#173e32;
  font-size:8px;
  line-height:1.35;
}

.gov-user small,
.gov-role small,
.gov-session small{
  display:block;
  margin-top:3px;
  color:#6f7f77;
  font-size:6px;
}

.gov-user em,
.gov-role em,
.gov-session em{
  display:block;
  margin-top:3px;
  color:#86928c;
  font-size:5px;
  font-style:normal;
}

/* badges */
.gov-mfa{
  max-width:160px;
  min-height:27px;
  border-radius:8px;
  padding:5px 7px;
  display:flex;
  align-items:center;
  gap:5px;
  font-size:6px;
  font-weight:800;
}

.gov-mfa.active{
  background:#e9f7f0;
  color:#1c704f;
}

.gov-mfa.pending{
  background:#fff0d7;
  color:#7d5d1d;
}

.gov-mfa .admin-svg-icon{
  width:13px !important;
  height:13px !important;
  min-width:13px !important;
  max-width:13px !important;
}

.gov-account-status{
  display:inline-flex;
  align-items:center;
  border-radius:999px;
  padding:5px 8px;
  font-size:6px;
  font-weight:800;
}

.gov-account-status.active{
  background:#eaf6f0;
  color:#1e6e50;
}

.gov-account-status.suspended{
  background:#fbe8e8;
  color:#92484b;
}

.gov-row-actions{
  display:flex;
  gap:5px;
  align-items:center;
}

.gov-row-actions button{
  min-height:28px;
  border-radius:8px;
  border:1px solid #dfe6e2;
  background:#fff;
  color:#345247;
  padding:0 7px;
  font-size:6px;
}

.gov-row-actions button:first-child{
  width:29px;
  padding:0;
  display:grid;
  place-items:center;
}

/* RBAC */
.gov-rbac,
.gov-approvals,
.gov-audit{
  background:#fff;
  border:1px solid #e4e8ef;
  border-radius:15px;
  overflow:hidden;
  margin-bottom:14px;
}

.gov-rbac>header,
.gov-approvals>header,
.gov-audit>header{
  padding:15px 16px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  border-bottom:1px solid #e8ebf1;
}

.gov-rbac h2,
.gov-approvals h2,
.gov-audit h2{
  margin:0;
  color:#153d31;
  font-size:16px;
}

.gov-rbac header p,
.gov-approvals header p,
.gov-audit header p{
  margin:4px 0 0;
  color:#7a8881;
  font-size:7px;
}

.gov-rbac header>span,
.gov-approvals header>b,
.gov-audit header>b{
  min-width:34px;
  height:34px;
  border-radius:50%;
  display:grid;
  place-items:center;
  background:#eef2ff;
  color:#183f33;
  font-size:8px;
}

.gov-rbac-table{
  overflow:auto;
}

.gov-rbac-head,
.gov-rbac-row{
  min-width:980px;
  display:grid;
  grid-template-columns:1.5fr repeat(6,1fr);
  gap:0;
}

.gov-rbac-head{
  background:#eef2ff;
  color:#617169;
}

.gov-rbac-head>*,
.gov-rbac-row>*{
  min-height:46px;
  padding:0 9px;
  display:flex;
  align-items:center;
  justify-content:center;
  border-inline-end:1px solid #e8ebf1;
  border-bottom:1px solid #e8ebf1;
  font-size:6px;
  text-align:center;
}

.gov-rbac-head>span,
.gov-rbac-row>span{
  justify-content:flex-start;
  font-weight:800;
  color:#29483c;
}

.gov-rbac-row i{
  font-style:normal;
  font-size:9px;
  font-weight:800;
}

.gov-rbac-row i.yes{color:#1e9f6d}
.gov-rbac-row i.no{color:#a4aaa7}

/* approvals */
.gov-approval-list{
  padding:12px;
  display:grid;
  gap:8px;
}

.gov-approval-list article{
  border:1px solid #e3e7ed;
  border-radius:11px;
  background:#fbfcff;
  padding:11px;
  display:grid;
  grid-template-columns:minmax(0,1fr) auto auto;
  gap:10px;
  align-items:center;
}

.gov-approval-list article>div:first-child small{
  color:#8a9790;
  font-size:5px;
}

.gov-approval-list h3{
  margin:3px 0;
  color:#193f33;
  font-size:9px;
}

.gov-approval-list p{
  margin:0;
  color:#75837c;
  font-size:6px;
}

.risk{
  border-radius:999px;
  padding:5px 8px;
  font-size:6px;
  font-weight:800;
}

.risk.high{background:#fbe4e5;color:#95494d}
.risk.medium{background:#fff0d5;color:#805e1c}
.risk.low{background:#e9f6f0;color:#1e704f}

.gov-approval-actions{
  display:flex;
  gap:5px;
}

.gov-approval-actions button{
  min-height:29px;
  border-radius:8px;
  padding:0 8px;
  border:1px solid #dce4df;
  background:#fff;
  color:#345247;
  font-size:6px;
  font-weight:800;
}

.gov-approval-actions button:first-child{
  background:#0b4a3b;
  color:#fff;
  border-color:#0b4a3b;
}

/* Audit */
.gov-audit-list{
  padding:10px 12px 13px;
  display:grid;
  gap:6px;
}

.gov-audit-list article{
  min-height:52px;
  border:1px solid #e4e8ef;
  border-radius:10px;
  background:#fbfcff;
  padding:9px 10px;
  display:grid;
  grid-template-columns:30px minmax(0,1fr) auto auto;
  gap:9px;
  align-items:center;
}

.gov-audit-list article>span{
  width:28px;
  height:28px;
  border-radius:8px;
  background:#eef2ff;
  color:#0b4a3b;
  display:grid;
  place-items:center;
