.supplier-kicker{
  display:flex;
  align-items:center;
  gap:7px;
  color:#8d6d2d;
  font-size:7px;
  font-weight:800;
  margin-bottom:7px;
  flex-wrap:wrap;
}

.supplier-kicker>.admin-svg-icon{
