}

/* KPIs */
.supplier-kpis{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:10px;
  margin-bottom:13px;
}

.supplier-kpis article{
  min-height:118px;
  background:#fff;
  border:1px solid #e3e7ee;
  border-radius:14px;
  padding:14px;
  display:flex;
  align-items:flex-start;
  gap:10px;
  box-shadow:0 7px 18px rgba(27,42,37,.035);
  position:relative;
  overflow:hidden;
}

.supplier-kpis article::after{
  content:"";
  position:absolute;
  inset-inline-start:0;
  top:0;
  bottom:0;
  width:4px;
  background:#0b4a3b;
}

.supplier-kpis article:nth-child(2)::after{background:#3dd79d}
.supplier-kpis article:nth-child(3)::after{background:#c99a3f}
.supplier-kpis article:nth-child(4)::after{background:#546f87}

.supplier-kpis article>.admin-svg-icon{
  width:31px !important;
  height:31px !important;
  min-width:31px !important;
  max-width:31px !important;
  border-radius:9px;
  padding:7px;
  box-sizing:border-box;
  background:#eef2ff;
  color:#0b4a3b;
}

.supplier-kpis small{
  display:block;
  color:#728178;
  font-size:6px;
  margin-bottom:8px;
}

.supplier-kpis strong{
  display:block;
  color:#153d31;
  font-size:22px;
  line-height:1;
  margin-bottom:6px;
  overflow-wrap:anywhere;
}

.supplier-kpis span{
  display:block;
  color:#65776e;
  font-size:6px;
  line-height:1.45;
}

/* Controls */
.supplier-controls{
  background:#fff;
  border:1px solid #e4e8ef;
  border-radius:13px;
  padding:12px;
  margin-bottom:12px;
  display:grid;
  grid-template-columns:minmax(250px,1.35fr) minmax(0,1fr);
  gap:10px;
}

.supplier-search,
.supplier-filter-grid label{
  min-height:39px;
  border:1px solid #dce4df;
  border-radius:9px;
  background:#fbfcff;
  display:flex;
  align-items:center;
  gap:7px;
  padding:0 10px;
}

.supplier-search input{
  width:100%;
  min-width:0;
  border:0;
  outline:0;
  background:transparent;
  color:#29483c;
  font-size:7px;
}

.supplier-filter-grid{
  display:grid;
  grid-template-columns:1fr 1.25fr 1fr 38px;
  gap:6px;
}

.supplier-filter-grid select{
  width:100%;
  min-width:0;
  border:0;
  outline:none;
  background:transparent;
  color:#29483c;
  font-size:7px;
}

.supplier-filter-grid button{
  width:38px;
  height:39px;
  border-radius:9px;
  border:1px solid #dce4df;
  background:#eef2ff;
  color:#29483c;
  display:grid;
  place-items:center;
}

/* Registry */
.supplier-registry{
  background:#fff;
  border:1px solid #e4e8ef;
  border-radius:15px;
  overflow:hidden;
  margin-bottom:15px;
  box-shadow:0 8px 22px rgba(27,42,37,.035);
}

.supplier-registry>header{
  min-height:63px;
  padding:13px 15px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  border-bottom:1px solid #e8ebf1;
}

.supplier-registry>header>div{
  display:flex;
  align-items:center;
  gap:8px;
  flex-wrap:wrap;
}

.supplier-registry>header i{
  width:8px;
  height:8px;
  border-radius:50%;
  background:#32d792;
  box-shadow:0 0 0 4px rgba(50,215,146,.10);
}

.supplier-registry h2{
  margin:0;
  color:#153d31;
  font-size:16px;
}

.supplier-registry header span{
  color:#7c8982;
  font-size:6px;
}

.supplier-registry header button{
  min-height:33px;
  border-radius:8px;
  padding:0 9px;
  background:#0b4a3b;
  color:#fff;
  display:flex;
  align-items:center;
  gap:6px;
  font-size:6px;
  font-weight:800;
}

.supplier-table-wrap{
  overflow:auto;
}

.supplier-registry table{
  width:100%;
  min-width:1180px;
  border-collapse:collapse;
}

.supplier-registry thead{
  background:#eef2ff;
}

.supplier-registry th{
  padding:10px 11px;
  text-align:start;
  color:#5f6f68;
  font-size:6px;
  font-weight:800;
}

.supplier-registry td{
  padding:11px;
  border-bottom:1px solid #edf0f4;
  vertical-align:middle;
  color:#344f45;
  font-size:7px;
}

.supplier-registry tbody tr:hover{
  background:#fbfcff;
}

/* supplier identity */
.supplier-name{
  display:grid;
  grid-template-columns:40px minmax(0,1fr);
  gap:8px;
  align-items:center;
  min-width:250px;
}

.supplier-name>span{
  width:38px;
  height:38px;
  border-radius:50%;
  background:#0b4a3b;
  color:#fff;
  display:grid;
  place-items:center;
  font-size:9px;
  font-weight:800;
}

.supplier-name b,
.supplier-type-cell b,
.supplier-performance b,
.supplier-supply b{
  display:block;
  color:#173e32;
  font-size:8px;
  line-height:1.35;
}

.supplier-name small,
.supplier-type-cell small,
.supplier-performance small,
.supplier-supply small{
  display:block;
  margin-top:3px;
  color:#6f7f77;
  font-size:6px;
}

.supplier-name em{
  display:block;
  margin-top:3px;
  color:#87938d;
  font-size:5px;
  font-style:normal;
}

.supplier-approval{
  display:inline-flex;
  align-items:center;
  gap:5px;
  border-radius:999px;
  padding:5px 8px;
  font-size:6px;
  font-weight:800;
  white-space:nowrap;
}

.supplier-approval.verified,
.supplier-approval.approved{
  background:#e9f6f0;
  color:#1d6f50;
}

.supplier-approval.review{
  background:#fff0d5;
  color:#7e5e1d;
}

.supplier-approval .admin-svg-icon{
  width:13px !important;
  height:13px !important;
  min-width:13px !important;
  max-width:13px !important;
}

/* quality */
.supplier-quality{
  min-width:105px;
}

.supplier-quality b{
  display:block;
  color:#173e32;
  font-size:8px;
  margin-bottom:5px;
}

.supplier-quality i{
  display:block;
  height:6px;
  border-radius:999px;
  background:#edf0ef;
  overflow:hidden;
}

.supplier-quality u{
  display:block;
  height:100%;
  border-radius:inherit;
  background:linear-gradient(90deg,#0b4a3b,#d0a244);
  text-decoration:none;
}

/* status and actions */
.supplier-status{
  display:inline-flex;
  align-items:center;
  border-radius:999px;
  padding:5px 8px;
  font-size:6px;
  font-weight:800;
}

.supplier-status.active{
  background:#eaf6f0;
  color:#1e704f;
}

.supplier-status.suspended{
  background:#fbe6e7;
  color:#94494e;
}

.supplier-actions{
  display:flex;
  align-items:center;
  gap:5px;
  flex-wrap:wrap;
  min-width:170px;
}

.supplier-actions button{
  min-height:29px;
  border-radius:8px;
  border:1px solid #dce4df;
  background:#fff;
  color:#345247;
  padding:0 8px;
  font-size:6px;
  font-weight:800;
}

.supplier-actions button:nth-child(2){
  background:#eef6f2;
  color:#176c4d;
}

/* Footer */
.supplier-registry>footer{
  min-height:57px;
  padding:10px 13px;
  background:#fbfcff;
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:12px;
}

.supplier-registry>footer small{
  display:block;
  color:#718078;
  font-size:6px;
  margin-bottom:4px;
}

.supplier-registry>footer b{
  color:#173e32;
  font-size:12px;
}

.supplier-registry>footer>span{
  color:#75837c;
  font-size:6px;
  text-align:end;
}

/* Dialog */
.supplier-dialog{
  width:min(680px,calc(100vw - 28px));
  border:0;
  border-radius:18px;
  padding:0;
  background:#fff;
  box-shadow:0 26px 76px rgba(13,62,48,.22);
}

.supplier-dialog::backdrop{
  background:rgba(7,37,29,.5);
  backdrop-filter:blur(4px);
}

.supplier-dialog>.close{
  position:absolute;
  top:12px;
  inset-inline-end:12px;
  width:34px;
  height:34px;
  border-radius:9px;
  background:#fff;
  border:1px solid #dce4df;
  z-index:2;
}

.supplier-modal{
  padding:23px;
}

.supplier-modal>small{
  display:block;
  color:#93712f;
  font-size:7px;
  font-weight:800;
  letter-spacing:.7px;
}

.supplier-modal h2{
  margin:6px 0 14px;
  color:#173e32;
  font-size:20px;
}

.supplier-modal form{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:10px;
}

.supplier-modal label{
  display:grid;
  gap:5px;
  color:#405b50;
  font-size:7px;
  font-weight:800;
}

.supplier-modal input,
.supplier-modal select,
.supplier-modal textarea{
  width:100%;
  border:1px solid #dbe4df;
  border-radius:9px;
  background:#fbfcfb;
  padding:0 10px;
  color:#173e32;
  font-size:8px;
  box-sizing:border-box;
}

.supplier-modal input,
.supplier-modal select{
  min-height:40px;
}

.supplier-modal textarea{
  min-height:82px;
  padding-top:9px;
  resize:vertical;
}

.supplier-modal .checkout-cta{
  grid-column:1/-1;
  min-height:41px;
  border-radius:10px;
  background:#0b4a3b;
  color:#fff;
  font-size:8px;
  font-weight:800;
}

/* Detail */
.supplier-detail-head{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:12px;
  margin-bottom:12px;
}

.supplier-detail-head h2{
  margin-bottom:4px;
}

.supplier-detail-head p{
  margin:0;
  color:#74827a;
  font-size:7px;
}

.supplier-detail-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:8px;
}

.supplier-detail-grid>div,
.supplier-detail>section{
  border:1px solid #e1e6e3;
  border-radius:10px;
  background:#fbfcff;
  padding:10px;
}

.supplier-detail-grid span,
.supplier-detail>section>span{
  display:block;
  color:#7a8881;
  font-size:6px;
  margin-bottom:5px;
}

.supplier-detail-grid b{
  display:block;
  color:#173e32;
  font-size:8px;
  overflow-wrap:anywhere;
}

.supplier-detail>section{
  margin-top:9px;
}

.supplier-detail>section p{
  margin:0;
  color:#344f45;
  font-size:8px;
  line-height:1.65;
}

.supplier-detail>footer{
  margin-top:12px;
  border-radius:10px;
  padding:9px 10px;
  background:#e9f6f0;
  color:#1e6d4e;
  display:flex;
  gap:7px;
  align-items:center;
  font-size:6px;
  font-weight:800;
}

/* RTL / LTR */
html[dir="ltr"] .supplier-banner,
html[dir="ltr"] .supplier-hero,
html[dir="ltr"] .supplier-kpis,
html[dir="ltr"] .supplier-controls,
html[dir="ltr"] .supplier-registry,
html[dir="ltr"] .supplier-dialog{
  direction:ltr;
  text-align:left;
}

html[dir="rtl"] .supplier-banner,
html[dir="rtl"] .supplier-hero,
html[dir="rtl"] .supplier-kpis,
html[dir="rtl"] .supplier-controls,
html[dir="rtl"] .supplier-registry,
html[dir="rtl"] .supplier-dialog{
  direction:rtl;
  text-align:right;
}

/* Responsive */
@media(max-width:1180px){
  .supplier-kpis{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
  .supplier-controls{
    grid-template-columns:1fr;
  }
}

@media(max-width:900px){
  .supplier-hero{
    flex-direction:column;
  }
  .supplier-hero-actions{
    width:100%;
  }
  .supplier-filter-grid{
    grid-template-columns:1fr 1fr;
  }
  .supplier-detail-grid{
    grid-template-columns:1fr 1fr;
  }
}

@media(max-width:760px){
  .reference-admin-content:has(.supplier-hero){
    border-radius:0;
  }
  .supplier-banner{
    align-items:flex-start;
    flex-direction:column;
    padding:10px;
  }
  .supplier-hero{
    border-radius:14px;
    padding:15px;
  }
  .supplier-hero h1{
    font-size:23px;
  }
  .supplier-hero-actions{
    display:grid;
    grid-template-columns:1fr;
  }
  .supplier-hero-actions button{
    justify-content:center;
  }
  .supplier-kpis{
    grid-template-columns:1fr 1fr;
    gap:8px;
  }
  .supplier-filter-grid{
    grid-template-columns:1fr;
  }
  .supplier-filter-grid button{
    width:100%;
  }
  .supplier-registry>header,
  .supplier-registry>footer{
    align-items:flex-start;
    flex-direction:column;
  }
  .supplier-registry>header>button{
    width:100%;
    justify-content:center;
  }
  .supplier-registry>footer>span{
    text-align:start;
  }
  .supplier-modal form{
    grid-template-columns:1fr;
  }
  .supplier-modal .checkout-cta{
    grid-column:auto;
  }
  .supplier-detail-grid{
    grid-template-columns:1fr;
  }
  .supplier-detail-head{
    flex-direction:column;
  }
}

@media(max-width:520px){
  .supplier-kpis{
    grid-template-columns:1fr;
  }
}


