  align-items:flex-start;
  justify-content:space-between;
  gap:12px;
  margin-bottom:14px;
}

.finance-health-card>header small{
  display:block;
  color:#7a8881;
  font-size:6px;
  margin-bottom:5px;
}

.finance-health-card>header h2{
  margin:0;
  color:#153d31;
  font-size:25px;
}

.finance-health-card>header p{
  margin:4px 0 0;
  color:#5f6f68;
  font-size:6px;
}

.finance-health-card>header>.admin-svg-icon{
  width:34px !important;
  height:34px !important;
  min-width:34px !important;
  max-width:34px !important;
  border-radius:10px;
  padding:8px;
  box-sizing:border-box;
  background:#eef2ff;
  color:#0b4a3b;
}

.finance-progress i{
  display:block;
  height:8px;
  border-radius:999px;
  background:#edf0ef;
  overflow:hidden;
}

.finance-progress u{
  display:block;
  height:100%;
  border-radius:inherit;
  background:linear-gradient(90deg,#0b4a3b,#3ed49b);
  text-decoration:none;
}

.finance-progress span{
  display:block;
  margin-top:7px;
  color:#607168;
  font-size:7px;
}

.finance-health-card>footer{
  margin-top:14px;
  padding-top:10px;
  border-top:1px solid #edf0f4;
  color:#6f7f77;
  font-size:6px;
}

.finance-mini-list{
  display:grid;
  gap:8px;
}

.finance-mini-list span{
  min-height:42px;
  border-radius:9px;
  background:#f7f8fc;
  padding:8px 10px;
  color:#697970;
  font-size:6px;
}

.finance-mini-list b{
  display:block;
  margin-top:3px;
  color:#173e32;
  font-size:10px;
}

.finance-health-card>button{
  width:100%;
  min-height:36px;
  border-radius:9px;
  background:#0b4a3b;
  color:#fff;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:6px;
  font-size:7px;
  font-weight:800;
}

/* Recent invoices */
.finance-recent{
  background:#fff;
  border:1px solid #e4e8ef;
  border-radius:15px;
  overflow:hidden;
  margin-bottom:14px;
}

.finance-recent>header{
  padding:13px 15px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  border-bottom:1px solid #e8ebf1;
}

.finance-recent h2{
  margin:0;
  color:#153d31;
  font-size:16px;
}

.finance-recent header p{
  margin:4px 0 0;
  color:#7a8881;
  font-size:7px;
}

.finance-recent header button{
  min-height:31px;
  border-radius:8px;
  padding:0 9px;
  border:1px solid #dce4df;
  background:#eef2ff;
  color:#2d4c41;
  font-size:6px;
  font-weight:800;
}

.finance-recent>div{
  padding:10px 12px 12px;
  display:grid;
  gap:7px;
}

.finance-recent article{
  min-height:56px;
  border:1px solid #e5e9ef;
  border-radius:10px;
  background:#fbfcff;
  padding:9px 10px;
  display:grid;
  grid-template-columns:minmax(0,1.3fr) .65fr .7fr auto;
  gap:10px;
  align-items:center;
}

.finance-recent article>div b{
  display:block;
  color:#173e32;
  font-size:8px;
}

.finance-recent article small,
.finance-recent article span{
  color:#7a8881;
  font-size:6px;
}

.finance-recent article button{
  min-height:28px;
  border-radius:8px;
  border:1px solid #dce4df;
  background:#fff;
  color:#345247;
  padding:0 8px;
  font-size:6px;
}

/* Search / filters */
.finance-controls{
  background:#fff;
  border:1px solid #e4e8ef;
  border-radius:13px;
  padding:12px;
  margin-bottom:12px;
  display:grid;
  grid-template-columns:minmax(250px,1.4fr) minmax(0,.8fr);
  gap:10px;
}

.finance-search,
.finance-filter-grid label{
  min-height:39px;
  border:1px solid #dce4df;
  border-radius:9px;
  background:#fbfcff;
  display:flex;
  align-items:center;
  gap:7px;
  padding:0 10px;
}

.finance-search input{
  width:100%;
  min-width:0;
  border:0;
  outline:0;
  background:transparent;
  color:#29483c;
  font-size:7px;
}

.finance-filter-grid{
  display:grid;
  grid-template-columns:1.2fr 1.2fr 38px;
  gap:6px;
}

.finance-filter-grid select{
  width:100%;
  min-width:0;
  border:0;
  outline:none;
  background:transparent;
  color:#29483c;
  font-size:7px;
}

.finance-filter-grid button{
  width:38px;
  height:39px;
  border-radius:9px;
  border:1px solid #dce4df;
  background:#eef2ff;
  color:#29483c;
  display:grid;
  place-items:center;
}

/* Ledger */
.finance-ledger{
  background:#fff;
  border:1px solid #e4e8ef;
  border-radius:15px;
  overflow:hidden;
  margin-bottom:14px;
  box-shadow:0 8px 22px rgba(27,42,37,.035);
}

.finance-ledger>header{
  min-height:62px;
  padding:13px 15px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  border-bottom:1px solid #e8ebf1;
}

.finance-ledger>header>div{
  display:flex;
  align-items:center;
  gap:8px;
  flex-wrap:wrap;
}

.finance-ledger>header i{
  width:8px;
  height:8px;
  border-radius:50%;
  background:#32d792;
  box-shadow:0 0 0 4px rgba(50,215,146,.10);
}

.finance-ledger h2{
  margin:0;
  color:#153d31;
  font-size:16px;
}

.finance-ledger header span{
  color:#7c8982;
  font-size:6px;
}

.finance-ledger header button{
  min-height:33px;
  border-radius:8px;
  padding:0 9px;
  background:#0b4a3b;
  color:#fff;
  display:flex;
  align-items:center;
  gap:6px;
  font-size:6px;
  font-weight:800;
}

.finance-table-wrap{
  overflow:auto;
}

.finance-ledger table{
  width:100%;
  min-width:1080px;
  border-collapse:collapse;
}

.finance-ledger thead{
  background:#eef2ff;
}

.finance-ledger th{
  padding:10px 11px;
  text-align:start;
  color:#5f6f68;
  font-size:6px;
  font-weight:800;
}

.finance-ledger td{
  padding:11px;
  border-bottom:1px solid #edf0f4;
  vertical-align:middle;
  color:#344f45;
  font-size:7px;
}

.finance-ledger tbody tr:hover{
  background:#fbfcff;
}

.finance-id b,
.finance-customer b{
  display:block;
  color:#173e32;
  font-size:8px;
}

.finance-id small,
.finance-customer small{
  display:block;
  margin-top:3px;
  color:#7a8881;
  font-size:6px;
}

.finance-paid{color:#177050 !important}
.finance-outstanding{color:#9a5d24 !important}

/* status pills */
.finance-status{
  display:inline-flex;
  align-items:center;
  border-radius:999px;
  padding:5px 8px;
  font-size:6px;
  font-weight:800;
  white-space:nowrap;
}

.finance-status.collected{background:#e9f6f0;color:#1d6f50}
.finance-status.partial{background:#fff0d5;color:#7e5e1d}
.finance-status.due{background:#fce8e8;color:#93484d}
.finance-status.refunded{background:#eef2ff;color:#566783}
.finance-status.cancelled{background:#edf0ee;color:#5a6861}

.finance-actions{
  display:flex;
  gap:5px;
  flex-wrap:wrap;
}

.finance-actions button{
  min-height:29px;
  border-radius:8px;
  border:1px solid #dce4df;
  background:#fff;
  color:#345247;
  padding:0 8px;
  font-size:6px;
  font-weight:800;
}

.finance-actions button:nth-child(2){
  background:#eef6f2;
  color:#176c4d;
}

.finance-ledger>footer{
  min-height:58px;
  padding:10px 13px;
  background:#fbfcff;
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:8px;
}

.finance-ledger>footer>div{
  border-radius:9px;
  background:#f1f4fb;
  padding:8px 10px;
}

.finance-ledger>footer span{
  display:block;
  color:#738078;
  font-size:6px;
  margin-bottom:4px;
}

.finance-ledger>footer b{
  display:block;
  color:#173e32;
  font-size:11px;
}

/* Settlements */
.finance-settlements{
  background:#fff;
  border:1px solid #e4e8ef;
  border-radius:15px;
  overflow:hidden;
  margin-bottom:14px;
}

.finance-settlements>header{
  padding:14px 15px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  border-bottom:1px solid #e8ebf1;
}

.finance-settlements h2{
  margin:0;
  color:#153d31;
  font-size:16px;
}

.finance-settlements header p{
  margin:4px 0 0;
  color:#7a8881;
  font-size:7px;
}

.finance-settlements header button{
  min-height:33px;
  border-radius:8px;
  padding:0 9px;
  background:#0b4a3b;
  color:#fff;
  display:flex;
  align-items:center;
  gap:6px;
  font-size:6px;
  font-weight:800;
}

.finance-settlement-list{
  padding:12px;
  display:grid;
  gap:8px;
}

.finance-settlement-list article{
  border:1px solid #e4e8ef;
  border-radius:11px;
  background:#fbfcff;
  padding:10px;
  display:grid;
  grid-template-columns:minmax(0,1.3fr) .7fr .8fr auto auto;
  gap:10px;
  align-items:center;
}

.finance-settlement-list h3{
  margin:3px 0;
  color:#173e32;
  font-size:9px;
}

.finance-settlement-list small,
.finance-settlement-list p,
.finance-settlement-list span{
  color:#7a8881;
  font-size:6px;
}

.finance-settlement-list p{
  margin:0;
}

.finance-settlement-list b{
  display:block;
  margin-top:3px;
  color:#173e32;
  font-size:8px;
}

.finance-settlement-status{
  display:inline-flex;
  border-radius:999px;
  padding:5px 8px;
  font-size:6px !important;
  font-weight:800;
}

.finance-settlement-status.pending{background:#fff0d5;color:#805e1c}
.finance-settlement-status.completed{background:#e9f6f0;color:#1d6f50}

/* Dialog */
.finance-dialog{
  width:min(680px,calc(100vw - 28px));
  border:0;
  border-radius:18px;
  padding:0;
  background:#fff;
  box-shadow:0 26px 76px rgba(13,62,48,.22);
}

.finance-dialog::backdrop{
  background:rgba(7,37,29,.5);
  backdrop-filter:blur(4px);
}

.finance-dialog>.close{
  position:absolute;
  top:12px;
  inset-inline-end:12px;
  width:34px;
  height:34px;
  border-radius:9px;
  background:#fff;
  border:1px solid #dce4df;
  z-index:2;
}

.finance-modal{
  padding:23px;
}

.finance-modal>small{
  display:block;
  color:#93712f;
  font-size:7px;
  font-weight:800;
  letter-spacing:.7px;
}

.finance-modal h2{
  margin:6px 0 14px;
  color:#173e32;
  font-size:20px;
}

.finance-modal form{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:10px;
}

.finance-modal label{
  display:grid;
  gap:5px;
  color:#405b50;
  font-size:7px;
  font-weight:800;
}

.finance-modal input,
.finance-modal select,
.finance-modal textarea{
  width:100%;
  border:1px solid #dbe4df;
  border-radius:9px;
  background:#fbfcfb;
  padding:0 10px;
  color:#173e32;
  font-size:8px;
  box-sizing:border-box;
}

.finance-modal input,
.finance-modal select{
  min-height:40px;
}

.finance-modal textarea{
  min-height:82px;
  padding-top:9px;
  resize:vertical;
}

.finance-modal .checkout-cta{
  grid-column:1/-1;
  min-height:41px;
  border-radius:10px;
  background:#0b4a3b;
  color:#fff;
  font-size:8px;
  font-weight:800;
}

.finance-payment-summary,
.invoice-grid{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:8px;
  margin-bottom:12px;
}

.finance-payment-summary>div,
.invoice-grid>div,
.invoice-view>section{
  border:1px solid #e1e6e3;
  border-radius:10px;
  background:#fbfcff;
  padding:10px;
}

.finance-payment-summary span,
.invoice-grid span,
.invoice-view>section>span{
  display:block;
  color:#7a8881;
  font-size:6px;
  margin-bottom:5px;
}

.finance-payment-summary b,
.invoice-grid b{
  display:block;
  color:#173e32;
  font-size:8px;
}

.invoice-head{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:12px;
  margin-bottom:12px;
}

.invoice-head h2{
  margin-bottom:4px;
}

.invoice-head p{
  margin:0;
  color:#74827a;
  font-size:7px;
}

.invoice-view>section{
  margin-top:8px;
}

.invoice-view>section p{
  margin:0;
  color:#344f45;
  font-size:8px;
  line-height:1.65;
}

.invoice-view>footer{
  margin-top:12px;
  border-radius:10px;
  padding:9px 10px;
  background:#e9f6f0;
  color:#1e6d4e;
  display:flex;
  gap:7px;
  align-items:center;
  font-size:6px;
  font-weight:800;
}

/* Direction */
html[dir="ltr"] .finance-banner,
html[dir="ltr"] .finance-hero,
html[dir="ltr"] .finance-kpis,
html[dir="ltr"] .finance-tabs,
html[dir="ltr"] .finance-overview-grid,
html[dir="ltr"] .finance-controls,
html[dir="ltr"] .finance-ledger,
html[dir="ltr"] .finance-settlements,
html[dir="ltr"] .finance-dialog{
  direction:ltr;
  text-align:left;
}

html[dir="rtl"] .finance-banner,
html[dir="rtl"] .finance-hero,
html[dir="rtl"] .finance-kpis,
html[dir="rtl"] .finance-tabs,
html[dir="rtl"] .finance-overview-grid,
html[dir="rtl"] .finance-controls,
html[dir="rtl"] .finance-ledger,
html[dir="rtl"] .finance-settlements,
html[dir="rtl"] .finance-dialog{
  direction:rtl;
  text-align:right;
}

/* Responsive */
@media(max-width:1180px){
  .finance-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}
  .finance-overview-grid{grid-template-columns:1fr 1fr}
  .finance-health-card:first-child{grid-column:1/-1}
  .finance-controls{grid-template-columns:1fr}
}

@media(max-width:900px){
  .finance-hero{flex-direction:column}
  .finance-hero-actions{width:100%}
  .finance-filter-grid{grid-template-columns:1fr 1fr}
  .finance-recent article{grid-template-columns:1fr .7fr auto}
  .finance-recent article>button{grid-column:1/-1}
  .finance-payment-summary,
  .invoice-grid{grid-template-columns:1fr 1fr}
}

@media(max-width:760px){
  .reference-admin-content:has(.finance-hero){border-radius:0}
  .finance-banner{
    align-items:flex-start;
    flex-direction:column;
    padding:10px;
  }
  .finance-hero{
    border-radius:14px;
    padding:15px;
  }
  .finance-hero h1{font-size:23px}
  .finance-hero-actions{
    display:grid;
    grid-template-columns:1fr;
  }
  .finance-hero-actions button{justify-content:center}
  .finance-kpis{
    grid-template-columns:1fr 1fr;
    gap:8px;
  }
  .finance-overview-grid{grid-template-columns:1fr}
  .finance-health-card:first-child{grid-column:auto}
  .finance-filter-grid{grid-template-columns:1fr}
  .finance-filter-grid button{width:100%}
  .finance-ledger>header,
  .finance-settlements>header,
  .finance-recent>header{
    align-items:flex-start;
    flex-direction:column;
  }
  .finance-ledger>header button,
  .finance-settlements>header button{
    width:100%;
    justify-content:center;
  }
  .finance-ledger>footer{grid-template-columns:1fr}
  .finance-settlement-list article{grid-template-columns:1fr}
  .finance-modal form{grid-template-columns:1fr}
  .finance-modal .checkout-cta{grid-column:auto}
  .finance-payment-summary,
  .invoice-grid{grid-template-columns:1fr}
  .invoice-head{flex-direction:column}
}

@media(max-width:520px){
  .finance-kpis{grid-template-columns:1fr}
}


/* =====================================================================
   KABSH NAJD — ORDERS & SLAUGHTERHOUSE OPERATIONS v44
   Backend-connected slaughterhouse / vet / preparation workflow
   ===================================================================== */

/* Operations summary cards */
.ops-summary{
  display:grid;
  grid-template-columns:repeat(5,minmax(0,1fr));
  gap:10px;
  margin:12px 0;
}

.ops-summary article{
  min-height:96px;
  background:#fff;
  border:1px solid #e4e8ef;
  border-radius:13px;
  padding:12px;
  display:flex;
  gap:9px;
  align-items:flex-start;
  position:relative;
  overflow:hidden;
  box-shadow:0 6px 18px rgba(27,42,37,.035);
}

.ops-summary article::after{
  content:"";
  position:absolute;
  inset-inline-start:0;
  top:0;
  bottom:0;
  width:3px;
  background:#0b4a3b;
}

.ops-summary article:nth-child(2)::after{background:#36d39a}
.ops-summary article:nth-child(3)::after{background:#c99a3f}
.ops-summary article:nth-child(4)::after{background:#5b6f92}
.ops-summary article:nth-child(5)::after{background:#2f9d74}

.ops-summary .admin-svg-icon{
  width:29px !important;
  height:29px !important;
  min-width:29px !important;
  max-width:29px !important;
  border-radius:8px;
  padding:6px;
  box-sizing:border-box;
  background:#eef2ff;
  color:#0b4a3b;
}

.ops-summary small{
  display:block;
  color:#728178;
  font-size:6px;
  line-height:1.45;
  margin-bottom:6px;
}

.ops-summary b{
  display:block;
  color:#153d31;
  font-size:20px;
  line-height:1;
}

/* Slaughterhouse cards */
.ops-houses{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:10px;
  margin:0 0 14px;
}

.ops-houses article{
  background:#fff;
  border:1px solid #e4e8ef;
  border-radius:13px;
  padding:12px;
  box-shadow:0 6px 18px rgba(27,42,37,.03);
}

.ops-houses article>div:first-child{
  display:flex;
  align-items:flex-start;
  gap:8px;
  margin-bottom:10px;
}

.ops-live-dot{
  width:8px;
  height:8px;
  border-radius:50%;
  margin-top:4px;
  flex:0 0 8px;
}

.ops-live-dot.on{
  background:#36d49b;
  box-shadow:0 0 0 4px rgba(54,212,155,.11);
}

.ops-live-dot.off{
  background:#b3bbb7;
}

.ops-houses b{
  display:block;
  color:#173e32;
  font-size:8px;
  line-height:1.4;
}

.ops-houses small{
  display:block;
  color:#7a8881;
  font-size:6px;
  margin-top:3px;
}

.ops-house-stats{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:6px;
}

.ops-house-stats span{
  border-radius:8px;
  background:#f4f6fb;
  padding:7px;
  color:#75827b;
  font-size:5px;
}

.ops-house-stats b{
  margin-top:3px;
  font-size:9px;
}

/* Per-order operations strip */
.order-op-strip{
  margin:10px 0 12px;
  border:1px solid #dfe6e2;
  border-radius:11px;
  background:#f9fbfa;
  padding:10px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}

.order-op-strip.ready{
  background:#edf8f3;
  border-color:#cfeadd;
}

.order-op-strip.working{
  background:#f7f3e8;
  border-color:#eadfbd;
}

.order-op-strip.failed{
  background:#fceeee;
  border-color:#efcfd1;
}

.order-op-strip>button{
  min-height:31px;
  border-radius:8px;
  border:1px solid #dce4df;
  background:#0b4a3b;
  color:#fff;
  padding:0 9px;
  display:flex;
  align-items:center;
  gap:5px;
  font-size:6px;
  font-weight:800;
  white-space:nowrap;
}

.order-op-main{
  flex:1;
  min-width:0;
}

.order-op-title{
  display:flex;
