/* v89 — Verification media, digital reference & customer support */
.customer-invoice-reference,
.customer-verify-reference,
.customer-support-ref{
  margin:14px 0;
  padding:12px 14px;
  border:1px solid rgba(201,154,52,.38);
  border-radius:14px;
  background:linear-gradient(135deg,rgba(255,249,232,.96),rgba(255,255,255,.98));
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.9);
}
.customer-invoice-reference small,
.customer-verify-reference small,
.customer-support-ref small{color:#6d7f77;font-size:10px;font-weight:800}
.customer-invoice-reference code,
.customer-verify-reference code,
.customer-support-ref code{
  color:#0d4a38;
  font-size:11px;
  font-weight:900;
  letter-spacing:.7px;
  background:#fff;
  border:1px solid #e8dec1;
  border-radius:9px;
  padding:7px 9px;
  word-break:break-all;
}
.customer-media-gallery{
  margin-top:14px;
  padding:13px;
  border:1px solid #e8e1cf;
  border-radius:16px;
  background:linear-gradient(180deg,#fff,#fbfaf5);
}
