  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  margin-bottom:11px;
}
.customer-media-gallery>header small{
  display:block;
  color:#aa7c1d;
  font-size:8px;
  font-weight:900;
  letter-spacing:1.1px;
}
.customer-media-gallery>header h3{margin:3px 0 0;font-size:14px;color:#173d32}
.customer-media-gallery>header>span{
  min-width:28px;height:28px;border-radius:10px;
  display:grid;place-items:center;background:#0b503a;color:#fff;font-size:10px;font-weight:900;
  box-shadow:0 7px 16px rgba(11,80,58,.16);
}
.customer-media-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.customer-media-card{
  overflow:hidden;border-radius:14px;background:#fff;border:1px solid #e6e8e3;
  box-shadow:0 8px 20px rgba(19,59,47,.07);
