.customer-media-card video{display:block;width:100%;height:150px;object-fit:cover;background:#0e1b17}
.customer-media-card>div{padding:10px}
.customer-media-card b{display:block;font-size:11px;color:#153e32}
.customer-media-card small{display:block;margin-top:3px;color:#61766e;font-size:9px;line-height:1.45}
.customer-media-card em{display:block;margin-top:6px;color:#9a7a2c;font-size:8px;font-style:normal}
.track-media-count{
  display:inline-grid;place-items:center;min-width:18px;height:18px;padding:0 5px;border-radius:999px;
  background:#d7ad42;color:#17372d;font-size:8px;font-weight:900;margin-inline-start:5px
}
.customer-track-actions{grid-template-columns:repeat(4,minmax(0,1fr))}
.customer-support-modal{padding:8px 2px 2px}
.customer-support-head{display:flex;gap:12px;align-items:flex-start}
.customer-support-head>span{
  width:42px;height:42px;border-radius:14px;display:grid;place-items:center;
  background:linear-gradient(145deg,#0a5a40,#073d2f);color:#f6d36a;font-size:20px;font-weight:900;
  box-shadow:0 9px 20px rgba(7,61,47,.2)
