/* Admin preparation proof manager */
.ops-media-manager{
  margin-top:14px;padding:14px;border-radius:16px;
  border:1px solid #dfe8e3;background:linear-gradient(180deg,#fbfdfc,#f3f8f5)
}
.ops-media-manager>header{
  display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:12px
}
.ops-media-manager>header small{font-size:8px;font-weight:900;letter-spacing:1px;color:#b28121}
.ops-media-manager>header h3{margin:3px 0;font-size:14px;color:#113e31}
.ops-media-manager>header p{margin:0;color:#6d7e76;font-size:9px;line-height:1.5}
.ops-media-manager>header>span{
  min-width:30px;height:30px;border-radius:10px;display:grid;place-items:center;
  background:#0b503a;color:#fff;font-weight:900;font-size:10px
}
.ops-media-form{display:grid;grid-template-columns:140px 1fr 1fr 1fr auto;gap:8px;align-items:end}
.ops-media-form label{display:grid;gap:5px;font-size:8px;color:#5f726a;font-weight:800}
.ops-media-form input,.ops-media-form select{
  min-width:0;height:38px;border:1px solid #d9e3de;border-radius:10px;background:#fff;padding:0 9px;font-size:9px;color:#183e32
}
.ops-media-form button{
  height:38px;border-radius:10px;background:linear-gradient(145deg,#0c6247,#083f30);color:#fff;
  padding:0 13px;font-size:9px;font-weight:900;display:flex;align-items:center;gap:6px;white-space:nowrap
}
.ops-media-form button svg{width:15px;height:15px}
.ops-media-list{display:grid;gap:8px;margin-top:11px}
.ops-media-list>article{
  display:grid;grid-template-columns:52px minmax(0,1fr) 32px;gap:9px;align-items:center;
  padding:8px;border-radius:12px;background:#fff;border:1px solid #e3e9e6
}
.ops-media-preview{width:52px;height:46px;border-radius:9px;overflow:hidden;background:#0d1c17;display:grid;place-items:center;color:#f5cf67}
.ops-media-preview img{width:100%;height:100%;object-fit:cover}
.ops-media-list b{display:block;font-size:9px;color:#143e32}
.ops-media-list small{display:block;margin-top:2px;color:#61746d;font-size:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ops-media-list em{display:block;margin-top:3px;color:#a17c2c;font-size:7px;font-style:normal}
.ops-media-list [data-remove-order-media]{
  width:30px;height:30px;border-radius:9px;background:#fff1ef;color:#a63c32;font-size:18px;font-weight:700
}

@media(max-width:900px){
  .ops-media-form{grid-template-columns:1fr 1fr}
  .ops-media-form button{grid-column:1/-1;justify-content:center}
}
@media(max-width:620px){
  .customer-track-actions{grid-template-columns:1fr 1fr}
  .customer-media-grid{grid-template-columns:1fr}
  .customer-media-card img,.customer-media-card video{height:180px}
  .customer-invoice-reference,.customer-verify-reference,.customer-support-ref{align-items:flex-start;flex-direction:column}
  .ops-media-form{grid-template-columns:1fr}
  .ops-media-form button{grid-column:auto}
}


