/* =====================================================================
   v96 — HERO EDGE + CINEMATIC BLEND STABILIZATION
   Removes side slivers/gaps and replaces the foggy seam with a clean,
   layered emerald-to-photo transition. Keeps v94 slider behaviour intact.
   ===================================================================== */
.v94-hero-slider{
  overflow:visible!important;
}
.v94-hero-slider .hero-slides{
  overflow:visible!important;
}
.v94-hero-slider .hero-slide{
  column-gap:0!important;
  background:#043c2e!important;
  background-clip:padding-box!important;
}

/* Make both grid panels meet perfectly with no exposed strip. */
.v94-hero-slider .hero-slide .hero-copy{
  position:relative!important;
  z-index:4!important;
  margin:0!important;
  border:0!important;
  overflow:visible!important;
}
.v94-hero-slider .hero-slide .luxury-hero-media{
  position:relative!important;
  z-index:2!important;
  align-self:stretch!important;
  min-width:0!important;
  width:calc(100% + 2px)!important;
  margin:0 -2px 0 0!important;
  padding:0!important;
  border:0!important;
  overflow:hidden!important;
  background:#063e30!important;
}
html[dir="rtl"] .v94-hero-slider .hero-slide .luxury-hero-media{
  margin:0 0 0 -2px!important;
}

/* Image intentionally bleeds 1px beyond the media box to eliminate edge seams. */
.v94-hero-slider .hero-slide .luxury-hero-media img{
  position:absolute!important;
  top:-1px!important;
  right:-1px!important;
  bottom:-1px!important;
  left:-1px!important;
  width:calc(100% + 2px)!important;
  height:calc(100% + 2px)!important;
  max-width:none!important;
  object-fit:cover!important;
  transform:scale(1.018)!important;
  filter:saturate(1.055) contrast(1.025) brightness(1.01)!important;
  -webkit-mask-image:none!important;
  mask-image:none!important;
}
.v94-hero-slider .hero-slide.is-active .luxury-hero-media img{
  transform:scale(1.008)!important;
}

/* Smooth photo-side blend. No blur: this avoids the cloudy/foggy patch. */
.v94-hero-slider .hero-slide .luxury-hero-media::before{
  content:""!important;
  display:block!important;
  position:absolute!important;
  z-index:4!important;
  top:0!important;
  bottom:0!important;
  left:0!important;
  width:180px!important;
  pointer-events:none!important;
  transform:none!important;
  filter:none!important;
  opacity:1!important;
  background:linear-gradient(90deg,
    #043f30 0%,
    rgba(4,63,48,.98) 12%,
    rgba(4,63,48,.88) 27%,
    rgba(4,63,48,.66) 46%,
    rgba(4,63,48,.38) 64%,
    rgba(4,63,48,.14) 82%,
    rgba(4,63,48,0) 100%
  )!important;
