  left:auto!important;
  right:0!important;
  background:linear-gradient(270deg,
    #043f30 0%,
    rgba(4,63,48,.98) 12%,
    rgba(4,63,48,.88) 27%,
    rgba(4,63,48,.66) 46%,
    rgba(4,63,48,.38) 64%,
    rgba(4,63,48,.14) 82%,
    rgba(4,63,48,0) 100%
  )!important;
}

/* Copy-side overlap bridges the exact grid join so no vertical boundary remains. */
.v94-hero-slider .hero-slide .hero-copy::after{
  content:"";
  position:absolute;
  z-index:-1;
  top:0;
  bottom:0;
  right:-86px;
  width:118px;
  pointer-events:none;
  background:linear-gradient(90deg,
    rgba(4,63,48,1) 0%,
    rgba(4,63,48,.92) 28%,
    rgba(4,63,48,.62) 56%,
    rgba(4,63,48,.26) 78%,
    rgba(4,63,48,0) 100%
  );
}
html[dir="rtl"] .v94-hero-slider .hero-slide .hero-copy::after{
