.product-details-link:hover{color:#b17c18}
.product-details-link span{font-size:13px}

.product-detail-page{padding:22px 26px 34px;display:grid;gap:22px;max-width:1260px;margin:0 auto;width:100%}
.product-detail-breadcrumbs{display:flex;align-items:center;gap:8px;flex-wrap:wrap;color:#7a8781;font-size:8px}
.product-detail-breadcrumbs button{font-size:8px;color:#0a5a44;font-weight:800;padding:0}
.product-detail-breadcrumbs b{color:#24372f}
.product-detail-breadcrumbs span{color:#c2cbc7}

.product-detail-hero{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(380px,.95fr);gap:26px;align-items:stretch}
.product-detail-gallery,.product-detail-info{background:#fff;border:1px solid #e3e9e6;border-radius:22px;box-shadow:0 16px 36px rgba(15,63,50,.08)}
.product-detail-gallery{padding:14px;display:grid;gap:11px}
.product-detail-main-image{position:relative;overflow:hidden;border-radius:16px;min-height:430px;background:#eef2ef}
