/* =========================================================
   v120 — Apple / iPhone Native System Typography
   Uses device-installed system fonts only; no font files loaded.
   ========================================================= */
:root{
  --kn-system-font:
    -apple-system,
    BlinkMacSystemFont,
    "SF Pro Text",
    "SF Pro Display",
    "Segoe UI",
    Roboto,
    Helvetica,
    Arial,
    sans-serif;
  --kn-arabic-system-font:
    -apple-system,
    BlinkMacSystemFont,
    "SF Arabic",
    "Geeza Pro",
    "Noto Sans Arabic",
    "Segoe UI",
    Tahoma,
    Arial,
    sans-serif;
}

html,
body,
button,
input,
textarea,
select,
option{
  font-family:var(--kn-system-font) !important;
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
  text-rendering:optimizeLegibility;
}

/* Keep all major UI copy on the same native typography system. */
body,
.app-shell,
.screen,
.site-header,
header,
nav,
main,
section,
article,
aside,
dialog,
.modal,
.card,
.product-card,
.ref-product-page,
.breed-profile,
.breed-profile-section,
.breed-card,
.ref-part-card,
.cart-shell,
.account-shell,
.track-shell,
.invoice-shell,
.verification-shell,
.admin-shell,
.toast{
  font-family:var(--kn-system-font) !important;
}

h1,h2,h3,h4,h5,h6,
p,span,small,strong,b,label,a,
button,input,textarea,select,option{
  font-family:inherit;
}

/* Apple-like hierarchy without changing existing sizes/layout. */
h1,h2,h3,
.product-card h3,
.ref-product-title,
.ref-parts-head h2,
.breed-profile h2,
.breed-profile-section h2,
.breed-card h3,
.modal h2,
.cart-shell h2,
.account-shell h2{
  letter-spacing:-0.018em;
  font-feature-settings:"kern" 1,"liga" 1;
}

button,
.btn,
input,
textarea,
select{
  font-weight:500;
  letter-spacing:-0.006em;
}

/* Arabic / RTL: prefer Apple's Arabic system face when available. */
html[dir="rtl"],
html[dir="rtl"] body,
[dir="rtl"],
.lang-ar,
[lang="ar"]{
  font-family:var(--kn-arabic-system-font) !important;
}

html[dir="rtl"] button,
html[dir="rtl"] input,
html[dir="rtl"] textarea,
html[dir="rtl"] select,
html[dir="rtl"] option,
html[dir="rtl"] h1,
html[dir="rtl"] h2,
html[dir="rtl"] h3,
html[dir="rtl"] h4,
html[dir="rtl"] h5,
html[dir="rtl"] h6,
html[dir="rtl"] p,
html[dir="rtl"] span,
html[dir="rtl"] small,
html[dir="rtl"] strong,
html[dir="rtl"] label,
html[dir="rtl"] a{
  font-family:var(--kn-arabic-system-font) !important;
  letter-spacing:0;
}

/* Native iOS controls feel more natural while preserving custom design. */
@supports (-webkit-touch-callout:none){
  html,
  body,
  button,
  input,
  textarea,
  select{
    font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","SF Pro Display","SF Arabic","Geeza Pro",sans-serif !important;
  }

  h1,h2,h3,h4,h5,h6,
  .ref-product-title,
  .breed-profile h2,
  .breed-profile-section h2{
    font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","SF Pro Text","SF Arabic","Geeza Pro",sans-serif !important;
  }
}

