    grid-row:1 / span 2!important;
    box-shadow:12px 0 34px rgba(0,18,13,.24)!important;
  }

  html[dir="rtl"] .reference-sidebar{
    grid-column:2!important;
    grid-row:1 / span 2!important;
    box-shadow:-12px 0 34px rgba(0,18,13,.24)!important;
  }

  /* Command bar is always the top row of the content column */
