/* =========================================================
   v185 — Full-width Dashboard Canvas Fit
   Removes desktop max-width caps that caused large empty side gutters.
   ========================================================= */
@media (min-width:901px){
  .reference-admin-content.is-dashboard{
    width:100%!important;
    max-width:none!important;
    margin:0!important;
    padding:18px 20px 38px!important;
    box-sizing:border-box!important;
  }

  .heritage-dashboard{
    width:100%!important;
    max-width:none!important;
    margin:0!important;
    padding:0!important;
    box-sizing:border-box!important;
  }

  .heritage-page-head,
  .heritage-kpis,
  .heritage-grid-main,
  .heritage-grid-bottom{
    width:100%!important;
    max-width:none!important;
  }
}

/* On extra-wide screens use the space instead of re-centering a narrow canvas. */
@media (min-width:1500px){
  .reference-admin-content.is-dashboard{
    padding-left:18px!important;
    padding-right:18px!important;
  }

  .heritage-dashboard{
    gap:18px!important;
  }

  .heritage-grid-main{
    grid-template-columns:minmax(0,2.15fr) minmax(340px,.85fr)!important;
  }

  .heritage-grid-bottom{
    grid-template-columns:minmax(0,2.1fr) minmax(320px,.9fr)!important;
  }
}


/* =========================================================
   v186 — STITCH PROJECT SHELL + DASHBOARD COMPOSITION MATCH
   Uses exact geometry/tokens from uploaded Stitch ai_01 + DESIGN.md.
   ========================================================= */

.stitch-shell-v186{
  --st-bg:#f9f9ff;
  --st-surface:#f9f9ff;
  --st-lowest:#ffffff;
  --st-low:#f0f3ff;
  --st-container:#e7eeff;
  --st-high:#dee8ff;
  --st-highest:#d8e3fb;
  --st-text:#111c2d;
  --st-muted:#414944;
  --st-outline:#c0c8c3;
  --st-primary:#002419;
  --st-primary-container:#0b3b2c;
  --st-primary-soft:#bdedd7;
  --st-gold:#c5a059;
  --st-gold-fixed:#ffdea5;
  --st-green:#4edea3;
  background:var(--st-bg)!important;
  color:var(--st-text)!important;
  font-family:"IBM Plex Sans Arabic","IBM Plex Sans",-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif!important;
}

/* ---------- Exact 288px Stitch sidebar shell ---------- */
@media (min-width:1101px){
  html[dir="ltr"] .stitch-shell-v186{
    display:grid!important;
    grid-template-columns:288px minmax(0,1fr)!important;
    grid-template-rows:80px auto!important;
    padding:0!important;
  }
  html[dir="rtl"] .stitch-shell-v186{
    display:grid!important;
    grid-template-columns:minmax(0,1fr) 288px!important;
    grid-template-rows:80px auto!important;
    padding:0!important;
  }

  .stitch-shell-v186 .reference-sidebar{
    position:sticky!important;
    top:0!important;
    width:288px!important;
    min-width:288px!important;
    max-width:288px!important;
    height:100vh!important;
    min-height:100vh!important;
    margin:0!important;
    padding:0!important;
    background:var(--st-lowest)!important;
    border:0!important;
    box-shadow:0 1px 8px rgba(0,0,0,.04)!important;
    overflow:hidden!important;
    z-index:50!important;
  }
  html[dir="ltr"] .stitch-shell-v186 .reference-sidebar{
    grid-column:1!important;grid-row:1/span 2!important;
    border-right:1px solid rgba(0,36,25,.04)!important;
  }
  html[dir="rtl"] .stitch-shell-v186 .reference-sidebar{
    grid-column:2!important;grid-row:1/span 2!important;
    border-left:1px solid rgba(0,36,25,.04)!important;
  }

  .stitch-shell-v186 .reference-admin-header.executive-command-bar{
    position:sticky!important;
    top:0!important;
    width:100%!important;
    min-height:80px!important;
    height:80px!important;
    margin:0!important;
    padding:0 32px!important;
    background:rgba(249,249,255,.92)!important;
    backdrop-filter:blur(18px)!important;
    border:0!important;
    border-radius:0!important;
    box-shadow:0 1px 8px rgba(0,0,0,.04)!important;
    z-index:40!important;
  }
  html[dir="ltr"] .stitch-shell-v186 .reference-admin-header.executive-command-bar{
    grid-column:2!important;grid-row:1!important;
  }
  html[dir="rtl"] .stitch-shell-v186 .reference-admin-header.executive-command-bar{
    grid-column:1!important;grid-row:1!important;
  }

  .stitch-shell-v186 .reference-admin-content{
    width:100%!important;
    max-width:none!important;
    min-width:0!important;
    margin:0!important;
    padding:24px 32px 40px!important;
    background:var(--st-bg)!important;
  }
  html[dir="ltr"] .stitch-shell-v186 .reference-admin-content{
    grid-column:2!important;grid-row:2!important;
  }
  html[dir="rtl"] .stitch-shell-v186 .reference-admin-content{
    grid-column:1!important;grid-row:2!important;
  }
}

/* Stitch brand block: 80px deep emerald */
.stitch-shell-v186 .reference-brand{
  height:80px!important;
  min-height:80px!important;
  padding:0 24px!important;
  margin:0!important;
  display:flex!important;
  align-items:center!important;
  gap:12px!important;
  background:var(--st-primary)!important;
  border:0!important;
}
.stitch-shell-v186 .reference-brand-mark{
  width:40px!important;height:40px!important;min-width:40px!important;max-width:40px!important;
  border-radius:12px!important;
  background:var(--st-primary-container)!important;
  border:0!important;
  box-shadow:none!important;
}
.stitch-shell-v186 .reference-brand-mark img{
  width:34px!important;height:34px!important;max-width:34px!important;max-height:34px!important;
  object-fit:contain!important;
  filter:brightness(2.2) saturate(.25)!important;
}
.stitch-shell-v186 .reference-brand b{
  color:#fff!important;
  font-size:16px!important;
  line-height:24px!important;
  font-weight:700!important;
}
.stitch-shell-v186 .reference-brand small{
  color:var(--st-primary-soft)!important;
  font-size:11px!important;
  line-height:18px!important;
  font-weight:400!important;
  letter-spacing:0!important;
}

/* Market strip directly under brand like Stitch */
.stitch-shell-v186 .reference-market-card{
  order:0!important;
  margin:0!important;
  min-height:48px!important;
  padding:10px 16px!important;
  border:0!important;
  border-radius:0!important;
  background:var(--st-low)!important;
  box-shadow:none!important;
}
.stitch-shell-v186 .reference-market-card b{
  color:var(--st-muted)!important;
  font-size:12px!important;
  line-height:16px!important;
  font-weight:600!important;
}
.stitch-shell-v186 .reference-market-card small{
  color:#717974!important;
  font-size:10px!important;
  line-height:14px!important;
}
.stitch-shell-v186 .reference-live-dot{
  width:8px!important;height:8px!important;background:var(--st-green)!important;
  box-shadow:0 0 0 4px rgba(78,222,163,.10)!important;
}

/* Navigation mirrors Stitch */
.stitch-shell-v186 .reference-nav{
  flex:1 1 auto!important;
  padding:16px 12px!important;
  gap:4px!important;
  overflow:auto!important;
}
.stitch-shell-v186 .reference-nav button{
  min-height:44px!important;
  padding:10px 12px!important;
  border-radius:12px!important;
  background:transparent!important;
  border:0!important;
  color:var(--st-muted)!important;
  font-size:14px!important;
  line-height:22px!important;
  font-weight:400!important;
  box-shadow:none!important;
}
.stitch-shell-v186 .reference-nav button:hover{
  background:var(--st-container)!important;
  color:var(--st-text)!important;
}
.stitch-shell-v186 .reference-nav button.active{
  background:var(--st-primary-container)!important;
  color:#fff!important;
  font-weight:600!important;
}
.stitch-shell-v186 .reference-nav button.active::before,
.stitch-shell-v186 .reference-nav button.active::after{display:none!important}
.stitch-shell-v186 .reference-nav .admin-svg-icon{
  width:20px!important;height:20px!important;min-width:20px!important;
}
.stitch-shell-v186 .reference-nav button>b{
  background:var(--st-gold-fixed)!important;
  color:#5d4201!important;
  border:0!important;
  box-shadow:none!important;
  font-size:10px!important;
}

/* Sidebar footer styled like Stitch account/footer block */
.stitch-shell-v186 .reference-sidebar-foot{
  margin-top:auto!important;
  padding:16px!important;
  border:0!important;
  background:var(--st-lowest)!important;
  box-shadow:0 -1px 8px rgba(0,0,0,.03)!important;
}
.stitch-shell-v186 .reference-sidebar-foot>button,
.stitch-shell-v186 .reference-secure{
  min-height:44px!important;
  border:0!important;
  border-radius:12px!important;
  background:var(--st-low)!important;
  color:var(--st-muted)!important;
  box-shadow:none!important;
}
.stitch-shell-v186 .reference-secure b{color:var(--st-text)!important;font-size:11px!important}
.stitch-shell-v186 .reference-secure small{color:#717974!important;font-size:9px!important}

/* ---------- Stitch topbar ---------- */
.stitch-dashboard-active .stitch-top-status{
  display:flex!important;
  align-items:center!important;
  gap:16px!important;
}
.stitch-dashboard-active .stitch-market-sync{
  display:inline-flex!important;
  align-items:center!important;
  gap:8px!important;
  min-height:32px!important;
  padding:6px 12px!important;
  border-radius:999px!important;
  background:var(--st-low)!important;
  color:var(--st-text)!important;
  font-size:12px!important;
  line-height:16px!important;
  font-weight:600!important;
}
.stitch-dashboard-active .stitch-market-sync i{
  width:10px!important;height:10px!important;border-radius:50%!important;
  background:var(--st-green)!important;
}
.stitch-dashboard-active .stitch-approved-count{
  display:inline-flex!important;
  align-items:center!important;
  gap:7px!important;
  color:var(--st-muted)!important;
  font-size:12px!important;
  line-height:18px!important;
}
.stitch-dashboard-active .stitch-approved-count .admin-svg-icon{
  width:16px!important;height:16px!important;
}

.stitch-shell-v186 .executive-header-actions{
  display:flex!important;
  align-items:center!important;
  gap:12px!important;
}
.stitch-shell-v186 .executive-head-icon,
.stitch-shell-v186 .executive-language-btn{
  width:40px!important;height:40px!important;min-width:40px!important;
  border-radius:12px!important;
  background:var(--st-container)!important;
  color:var(--st-muted)!important;
  border:0!important;
  box-shadow:none!important;
}
.stitch-shell-v186 .executive-language-btn{
  width:auto!important;min-width:64px!important;padding:0 12px!important;
}
.stitch-shell-v186 .executive-profile-pill{
  height:42px!important;
  min-width:250px!important;
  border-radius:12px!important;
  background:transparent!important;
  border:0!important;
  color:var(--st-text)!important;
  box-shadow:none!important;
}
.stitch-shell-v186 .executive-avatar{
  width:34px!important;height:34px!important;min-width:34px!important;
  background:var(--st-primary)!important;color:#fff!important;border:0!important;
}
.stitch-shell-v186 .executive-profile-pill b{color:var(--st-text)!important;font-size:11px!important}
.stitch-shell-v186 .executive-profile-pill small{color:var(--st-muted)!important;font-size:9px!important}
.stitch-shell-v186 .executive-bell-dot{background:#d9a51d!important;border-color:var(--st-container)!important}

/* ---------- Dashboard root ---------- */
.stitch-dashboard-v186{
  width:100%!important;
  max-width:none!important;
  margin:0!important;
  display:flex!important;
  flex-direction:column!important;
  gap:24px!important;
}

/* Exact dark emerald hero composition */
.stitch-hero-v186{
  position:relative!important;
  overflow:hidden!important;
  min-height:168px!important;
  padding:24px 32px!important;
  border-radius:12px!important;
  background:var(--st-primary)!important;
  color:#fff!important;
  box-shadow:0 10px 30px -4px rgba(11,59,44,.10)!important;
}
.stitch-hero-orb{
  position:absolute!important;border-radius:50%!important;filter:blur(48px)!important;pointer-events:none!important;
}
.stitch-hero-orb.one{
  width:320px!important;height:320px!important;left:-60px!important;bottom:-210px!important;
  background:rgba(0,60,39,.48)!important;
}
.stitch-hero-orb.two{
  width:240px!important;height:240px!important;right:30%!important;top:-160px!important;
  background:rgba(119,90,25,.18)!important;
}
html[dir="rtl"] .stitch-hero-orb.one{left:auto!important;right:-60px!important}
html[dir="rtl"] .stitch-hero-orb.two{right:auto!important;left:30%!important}

.stitch-hero-content{
  position:relative!important;z-index:2!important;
  display:flex!important;align-items:center!important;justify-content:space-between!important;gap:24px!important;
}
.stitch-hero-copy{max-width:820px!important}
.stitch-live-badge{
  display:inline-flex!important;align-items:center!important;gap:8px!important;
  min-height:28px!important;padding:5px 12px!important;border-radius:999px!important;
  background:var(--st-primary-container)!important;color:var(--st-green)!important;
  font-size:12px!important;line-height:16px!important;font-weight:600!important;
}
.stitch-live-badge i{
  width:8px!important;height:8px!important;border-radius:50%!important;background:var(--st-green)!important;
  box-shadow:0 0 0 5px rgba(78,222,163,.08)!important;
}
.stitch-hero-v186 h1{
  margin:8px 0 4px!important;color:#fff!important;
  font-size:28px!important;line-height:38px!important;font-weight:700!important;letter-spacing:-.25px!important;
}
.stitch-hero-v186 p{
  margin:0!important;max-width:820px!important;
  color:var(--st-primary-soft)!important;opacity:.90!important;
  font-size:14px!important;line-height:22px!important;
}
.stitch-hero-actions{
  display:flex!important;align-items:center!important;gap:12px!important;flex-wrap:wrap!important;justify-content:flex-end!important;
}
.stitch-time-card{
  min-height:50px!important;padding:9px 14px!important;border-radius:12px!important;
  display:flex!important;align-items:center!important;gap:10px!important;
  background:rgba(255,255,255,.08)!important;backdrop-filter:blur(8px)!important;
}
.stitch-time-card .admin-svg-icon{width:21px!important;height:21px!important;color:var(--st-gold-fixed)!important}
.stitch-time-card div{display:flex!important;flex-direction:column!important}
.stitch-time-card small{color:rgba(255,255,255,.62)!important;font-size:10px!important}
.stitch-time-card b{color:#fff!important;font-size:13px!important}
.stitch-gold-btn{
  min-height:50px!important;padding:0 18px!important;
  display:inline-flex!important;align-items:center!important;justify-content:center!important;gap:8px!important;
  border:0!important;border-radius:12px!important;
  background:var(--st-gold-fixed)!important;color:#5d4201!important;
  font-size:13px!important;font-weight:700!important;
  box-shadow:0 8px 20px rgba(119,90,25,.16)!important;cursor:pointer!important;
}
.stitch-gold-btn .admin-svg-icon{width:18px!important;height:18px!important}

/* Exact 5 KPI row */
.stitch-kpi-grid{
  display:grid!important;
  grid-template-columns:repeat(5,minmax(0,1fr))!important;
  gap:16px!important;
}
.stitch-kpi-grid article{
  min-width:0!important;
  min-height:148px!important;
  padding:20px!important;
  border-radius:12px!important;
  background:var(--st-lowest)!important;
  border:0!important;
  box-shadow:0 4px 20px -2px rgba(11,59,44,.05)!important;
  display:flex!important;flex-direction:column!important;justify-content:space-between!important;
}
.stitch-kpi-head{
  display:flex!important;align-items:center!important;justify-content:space-between!important;gap:10px!important;
}
.stitch-kpi-head>span{color:var(--st-muted)!important;font-size:12px!important;line-height:18px!important}
.stitch-kpi-head>i{
  width:32px!important;height:32px!important;display:grid!important;place-items:center!important;
  border-radius:8px!important;background:var(--st-container)!important;color:var(--st-primary-container)!important;font-style:normal!important;
}
.stitch-kpi-head>i.gold{background:var(--st-gold-fixed)!important;color:#5d4201!important}
.stitch-kpi-head .admin-svg-icon{width:17px!important;height:17px!important}
.stitch-kpi-grid article>strong{
  margin:8px 0!important;color:var(--st-text)!important;
  font-size:32px!important;line-height:38px!important;font-weight:700!important;letter-spacing:-.5px!important;
}
.stitch-kpi-meta{
  display:flex!important;align-items:center!important;gap:6px!important;
  color:var(--st-muted)!important;font-size:11px!important;line-height:16px!important;
}
.stitch-kpi-meta b{color:#005236!important;font-size:11px!important}
.stitch-kpi-meta.gold b{color:#785a1a!important}
.green-dot{width:8px!important;height:8px!important;border-radius:50%!important;background:var(--st-green)!important}

/* 8 / 4 Stitch middle grid */
.stitch-middle-grid{
  display:grid!important;
  grid-template-columns:minmax(0,8fr) minmax(320px,4fr)!important;
  gap:24px!important;
}
.stitch-panel{
  min-width:0!important;
  border-radius:12px!important;
  background:var(--st-lowest)!important;
  border:0!important;
  box-shadow:0 4px 20px -2px rgba(11,59,44,.05)!important;
  overflow:hidden!important;
}
.stitch-panel>header{
  display:flex!important;align-items:center!important;justify-content:space-between!important;gap:14px!important;
  padding:22px 24px 16px!important;
}
.stitch-title-cluster{
  display:flex!important;align-items:center!important;gap:12px!important;min-width:0!important;
}
.stitch-title-icon{
  width:40px!important;height:40px!important;min-width:40px!important;
  display:grid!important;place-items:center!important;border-radius:12px!important;
  background:var(--st-primary-container)!important;color:#fff!important;
}
.stitch-title-icon.gold{background:var(--st-gold-fixed)!important;color:#785a1a!important}
.stitch-title-icon .admin-svg-icon{width:21px!important;height:21px!important}
.stitch-title-cluster h2{
  margin:0!important;color:var(--st-text)!important;
  font-size:16px!important;line-height:24px!important;font-weight:600!important;
}
.stitch-title-cluster p{
  margin:1px 0 0!important;color:var(--st-muted)!important;
  font-size:12px!important;line-height:18px!important;
}
.stitch-score{
  padding:7px 10px!important;border-radius:999px!important;background:var(--st-container)!important;
  color:var(--st-muted)!important;font-size:11px!important;font-weight:600!important;
}

.stitch-stage-grid{
  display:grid!important;grid-template-columns:repeat(6,minmax(0,1fr))!important;gap:8px!important;padding:0 24px 18px!important;
}
.stitch-stage-grid button{
  min-height:72px!important;padding:10px!important;border-radius:10px!important;
  border:1px solid var(--st-outline)!important;background:#fff!important;
  display:grid!important;grid-template-columns:8px minmax(0,1fr) auto!important;align-items:center!important;gap:7px!important;
  color:var(--st-text)!important;cursor:pointer!important;
}
.stitch-stage-grid button>span{
  width:8px!important;height:8px!important;border-radius:50%!important;background:#929d98!important;
}
.stitch-stage-grid button>span.confirmed{background:#4e8fb4!important}
.stitch-stage-grid button>span.preparing{background:#f09b36!important}
.stitch-stage-grid button>span.ready{background:#67b943!important}
.stitch-stage-grid button>span.delivery{background:#d7a22c!important}
.stitch-stage-grid button>span.completed{background:#10b981!important}
.stitch-stage-grid button>b{
  overflow:hidden!important;text-overflow:ellipsis!important;white-space:nowrap!important;
  color:var(--st-muted)!important;font-size:10px!important;line-height:14px!important;font-weight:600!important;
}
.stitch-stage-grid button>strong{color:var(--st-text)!important;font-size:16px!important}

.stitch-flow-chart{
  padding:18px 24px 22px!important;border-top:1px solid rgba(192,200,195,.55)!important;
}
.stitch-chart-head{
  display:flex!important;align-items:center!important;justify-content:space-between!important;gap:12px!important;margin-bottom:14px!important;
}
.stitch-chart-head h3{margin:0!important;color:var(--st-text)!important;font-size:13px!important;line-height:18px!important;font-weight:600!important}
.stitch-chart-head p{margin:2px 0 0!important;color:var(--st-muted)!important;font-size:11px!important;line-height:16px!important}
.stitch-chart-head>span{
  padding:5px 9px!important;border-radius:999px!important;background:var(--st-low)!important;color:var(--st-muted)!important;
  font-size:10px!important;font-weight:600!important;
}
.stitch-bars{
  height:190px!important;display:flex!important;align-items:flex-end!important;justify-content:space-between!important;gap:10px!important;
}
.stitch-bars>div{
  flex:1 1 0!important;height:100%!important;display:flex!important;flex-direction:column!important;align-items:center!important;justify-content:flex-end!important;gap:8px!important;
}
.stitch-bars i{
  position:relative!important;width:100%!important;max-width:48px!important;height:calc(100% - 22px)!important;
  display:flex!important;align-items:flex-end!important;border-radius:9px 9px 3px 3px!important;background:var(--st-low)!important;font-style:normal!important;
}
.stitch-bars u{
  width:100%!important;min-height:5px!important;border-radius:9px 9px 3px 3px!important;
  background:linear-gradient(180deg,#5f947f,var(--st-primary-container))!important;text-decoration:none!important;
}
.stitch-bars i>b{
  position:absolute!important;top:-17px!important;left:50%!important;transform:translateX(-50%)!important;
  color:var(--st-muted)!important;font-size:9px!important;
}
.stitch-bars>div>span{color:#7a8680!important;font-size:9px!important;font-weight:600!important}

/* Guardrails card */
