/* =========================================================
   v196 — ADMIN RTL / ARABIC DESKTOP LAYOUT FIX
   Removes legacy double sidebar offset.
   The Stitch grid alone reserves the 288px sidebar space.
   ========================================================= */

@media (min-width:1101px){

  /* Critical: old v166 rules added 300px physical padding.
     v186+ already reserves a 288px grid column, so the old
     padding created a second empty sidebar-sized strip. */
  html[dir="ltr"] .reference-admin.stitch-shell-v186,
  html[dir="rtl"] .reference-admin.stitch-shell-v186{
    width:100%!important;
    max-width:none!important;
    min-width:0!important;
    margin:0!important;
    padding:0!important;
    box-sizing:border-box!important;
  }

  /* LTR: fixed sidebar on left, workspace in grid column 2 */
  html[dir="ltr"] .reference-admin.stitch-shell-v186{
    grid-template-columns:288px minmax(0,1fr)!important;
  }

  /* RTL: fixed sidebar on right, workspace in grid column 1 */
  html[dir="rtl"] .reference-admin.stitch-shell-v186{
    grid-template-columns:minmax(0,1fr) 288px!important;
  }

  html[dir="rtl"] .stitch-shell-v186 .reference-sidebar{
    right:0!important;
    left:auto!important;
    width:288px!important;
    min-width:288px!important;
    max-width:288px!important;
  }

  html[dir="ltr"] .stitch-shell-v186 .reference-sidebar{
    left:0!important;
    right:auto!important;
    width:288px!important;
    min-width:288px!important;
    max-width:288px!important;
  }

  /* Header always fills only the workspace column */
  html[dir="rtl"] .stitch-shell-v186 .reference-admin-header.executive-command-bar{
    grid-column:1!important;
    grid-row:1!important;
    width:100%!important;
    max-width:none!important;
    min-width:0!important;
    margin:0!important;
    inset-inline:0!important;
  }

  html[dir="ltr"] .stitch-shell-v186 .reference-admin-header.executive-command-bar{
    grid-column:2!important;
    grid-row:1!important;
    width:100%!important;
    max-width:none!important;
    min-width:0!important;
    margin:0!important;
    inset-inline:0!important;
  }

  /* Main content uses the complete remaining viewport width */
  html[dir="rtl"] .stitch-shell-v186 .reference-admin-content{
    grid-column:1!important;
    grid-row:2!important;
    width:100%!important;
    max-width:none!important;
    min-width:0!important;
    margin:0!important;
    padding-inline:32px!important;
    box-sizing:border-box!important;
  }

  html[dir="ltr"] .stitch-shell-v186 .reference-admin-content{
    grid-column:2!important;
    grid-row:2!important;
    width:100%!important;
    max-width:none!important;
    min-width:0!important;
    margin:0!important;
    padding-inline:32px!important;
    box-sizing:border-box!important;
  }

  /* Prevent module roots from retaining an old physical margin/offset */
  html[dir="rtl"] .stitch-shell-v186 .reference-admin-content > *,
  html[dir="ltr"] .stitch-shell-v186 .reference-admin-content > *{
    max-width:100%!important;
    min-width:0!important;
    margin-left:0!important;
    margin-right:0!important;
    box-sizing:border-box!important;
  }

  /* WhatsApp workspace: fluid within the corrected RTL/LTR canvas */
  .stitch-shell-v186 .wa-topbar,
  .stitch-shell-v186 .wa-grid{
    width:100%!important;
    max-width:100%!important;
    min-width:0!important;
    margin-inline:0!important;
    box-sizing:border-box!important;
  }

  html[dir="rtl"] .stitch-shell-v186 .wa-grid{
    direction:rtl!important;
  }

  /* Ensure the 3 WhatsApp columns fit the available workspace */
  .stitch-shell-v186 .wa-grid{
    grid-template-columns:minmax(220px,280px) minmax(420px,1fr) minmax(220px,285px)!important;
  }
}

/* Medium desktop / laptop: keep RTL fluid without horizontal spill */
@media (min-width:1101px) and (max-width:1399px){
  html[dir="rtl"] .stitch-shell-v186 .reference-admin-content,
  html[dir="ltr"] .stitch-shell-v186 .reference-admin-content{
    padding-inline:20px!important;
  }

  .stitch-shell-v186 .wa-grid{
    grid-template-columns:230px minmax(0,1fr) 230px!important;
  }
}

/* Absolute horizontal-overflow safety for admin in both directions */
body:has(.app-shell.admin-shell),
#app:has(.app-shell.admin-shell),
.app-shell.admin-shell,
.app-shell.admin-shell>.screen,
.reference-admin.stitch-shell-v186{
  max-width:100vw!important;
  overflow-x:hidden!important;
}


/* =========================================================
   v197 — FINAL RTL GRID GEOMETRY FIX
   Keep desktop grid geometry LTR; apply RTL only to content.
   This prevents the 288px sidebar track from being reserved
   on the physical LEFT side in Arabic mode.
   ========================================================= */

@media (min-width:1101px){

  /* IMPORTANT:
     CSS Grid line numbering follows direction.
     The old Arabic rule direction:rtl caused the sidebar track
     to be physically reserved on the left while the fixed
     sidebar itself was on the right.
     Geometry is therefore locked to LTR. */
  html[dir="rtl"] .reference-admin.stitch-shell-v186{
    direction:ltr!important;
    display:grid!important;
    grid-template-columns:minmax(0,1fr) 288px!important;
    grid-template-rows:80px minmax(calc(100vh - 80px),auto)!important;
    width:100%!important;
    max-width:none!important;
    min-width:0!important;
    margin:0!important;
    padding:0!important;
    overflow-x:hidden!important;
  }

  /* Physical right sidebar */
  html[dir="rtl"] .reference-admin.stitch-shell-v186 .reference-sidebar{
    position:fixed!important;
    top:0!important;
    right:0!important;
    left:auto!important;
    bottom:0!important;
    width:288px!important;
    min-width:288px!important;
    max-width:288px!important;
    height:100vh!important;
    max-height:100vh!important;
    direction:rtl!important;
    text-align:right!important;
    grid-column:2!important;
    grid-row:1 / span 2!important;
  }

  /* Workspace physically occupies everything LEFT of sidebar */
  html[dir="rtl"] .reference-admin.stitch-shell-v186 .reference-admin-header.executive-command-bar{
    grid-column:1!important;
    grid-row:1!important;
    direction:rtl!important;
    text-align:right!important;
    width:100%!important;
    max-width:none!important;
    min-width:0!important;
    margin:0!important;
    padding-inline:32px!important;
    box-sizing:border-box!important;
  }

  html[dir="rtl"] .reference-admin.stitch-shell-v186 .reference-admin-content{
    grid-column:1!important;
    grid-row:2!important;
    direction:rtl!important;
    text-align:right!important;
    width:100%!important;
    max-width:none!important;
    min-width:0!important;
    margin:0!important;
    padding-inline:32px!important;
    box-sizing:border-box!important;
    overflow-x:hidden!important;
  }

  /* Every module root must stay inside the workspace track */
  html[dir="rtl"] .reference-admin.stitch-shell-v186 .reference-admin-content > *{
    width:100%!important;
    max-width:100%!important;
    min-width:0!important;
    margin-left:0!important;
    margin-right:0!important;
    box-sizing:border-box!important;
    direction:rtl!important;
  }

  /* Dashboard grids: RTL text, stable physical track geometry */
  html[dir="rtl"] .stitch-dashboard-v186,
  html[dir="rtl"] .stitch-kpi-grid,
  html[dir="rtl"] .stitch-middle-grid,
  html[dir="rtl"] .stitch-three-grid,
  html[dir="rtl"] .stitch-stream-panel{
    direction:rtl!important;
    width:100%!important;
    max-width:100%!important;
    min-width:0!important;
  }

  /* Orders / Suppliers / Finance / AI / WhatsApp / Marketing /
     Governance / Audit all use the same corrected canvas. */
  html[dir="rtl"] .orders-control-center,
  html[dir="rtl"] .supplier-control-center,
  html[dir="rtl"] .finance-control-center,
  html[dir="rtl"] .ai-digital-center,
  html[dir="rtl"] .wa-topbar,
  html[dir="rtl"] .wa-grid,
  html[dir="rtl"] .marketing-control-center,
  html[dir="rtl"] .governance-control-center,
  html[dir="rtl"] .audit-control-center{
    direction:rtl!important;
    width:100%!important;
    max-width:100%!important;
    min-width:0!important;
    margin-inline:0!important;
    box-sizing:border-box!important;
  }

  /* WhatsApp needs explicit physical columns but RTL content */
  html[dir="rtl"] .wa-grid{
    grid-template-columns:minmax(220px,285px) minmax(0,1fr) minmax(220px,280px)!important;
  }

  /* Header actions remain correctly aligned in Arabic */
  html[dir="rtl"] .reference-admin-header .reference-header-actions,
  html[dir="rtl"] .reference-admin-header .executive-header-actions{
    margin-right:0!important;
    margin-left:auto!important;
    direction:rtl!important;
  }
}

/* Laptop width */
@media (min-width:1101px) and (max-width:1399px){
  html[dir="rtl"] .reference-admin.stitch-shell-v186 .reference-admin-header.executive-command-bar,
  html[dir="rtl"] .reference-admin.stitch-shell-v186 .reference-admin-content{
    padding-inline:20px!important;
  }

  html[dir="rtl"] .wa-grid{
    grid-template-columns:230px minmax(0,1fr) 230px!important;
  }
}


