   ========================================================= */

.wa-filter-slider{
  width:100%!important;
  min-width:0!important;
  margin-top:9px!important;
  display:grid!important;
  grid-template-columns:28px minmax(0,1fr) 28px!important;
  align-items:center!important;
  gap:5px!important;
  direction:ltr!important;
}

.wa-filter-slider .wa-filter-row{
  min-width:0!important;
  width:100%!important;
  margin-top:0!important;
  display:flex!important;
  flex-wrap:nowrap!important;
  gap:6px!important;
  overflow-x:auto!important;
  overflow-y:hidden!important;
  scroll-behavior:smooth!important;
  scroll-snap-type:x proximity!important;
  overscroll-behavior-inline:contain!important;
  scrollbar-width:none!important;
  -webkit-overflow-scrolling:touch!important;
  touch-action:pan-x!important;
  padding:2px 1px!important;
}

html[dir="rtl"] .wa-filter-slider .wa-filter-row{
  direction:rtl!important;
}

html[dir="ltr"] .wa-filter-slider .wa-filter-row{
  direction:ltr!important;
}

.wa-filter-slider .wa-filter-row::-webkit-scrollbar{
  display:none!important;
}

.wa-filter-slider .wa-filter-row button{
  flex:0 0 auto!important;
  min-width:max-content!important;
  scroll-snap-align:start!important;
}

.wa-filter-nav{
  width:28px!important;
  height:31px!important;
  min-width:28px!important;
  max-width:28px!important;
  padding:0!important;
  display:grid!important;
  place-items:center!important;
  border-radius:9px!important;
  border:1px solid #d7e3dd!important;
  background:linear-gradient(180deg,#ffffff,#f2f8f5)!important;
  color:#075e54!important;
  font-family:Arial,sans-serif!important;
  font-size:20px!important;
  line-height:1!important;
  font-weight:700!important;
  cursor:pointer!important;
  user-select:none!important;
  box-shadow:0 3px 8px rgba(7,94,84,.05)!important;
