  left:33px!important;
  background:linear-gradient(90deg,#fbfdfc,rgba(251,253,252,0))!important;
}

.wa-filter-slider::after{
  right:33px!important;
  background:linear-gradient(270deg,#fbfdfc,rgba(251,253,252,0))!important;
}

/* On touch devices keep arrows but make the strip easy to swipe. */
@media(max-width:760px){
  .wa-filter-slider{
