/* =====================================================================
   v313 — TRUE STICKY PRODUCT VISUAL FIX
   The customer app shell normally clips content with overflow:hidden,
   which prevents the product visual from sticking to the viewport.
   Unlock overflow only on product-detail pages and keep the visual
   pinned while the configuration/details column continues scrolling.
   ===================================================================== */
@media (min-width:821px){
  body:has(.ref-product-page),
  html:has(.ref-product-page),
  #app:has(.ref-product-page){
    overflow:visible!important;
  }

  body:has(.ref-product-page) .app-shell:not(.admin-shell){
    overflow:visible!important;
  }

  body:has(.ref-product-page) .app-shell:not(.admin-shell)>.screen,
  body:has(.ref-product-page) .ref-product-page,
  body:has(.ref-product-page) .ref-product-main{
    overflow:visible!important;
  }

  body:has(.ref-product-page) .ref-product-main{
    align-items:start!important;
  }

  body:has(.ref-product-page) .ref-product-visual{
    position:-webkit-sticky!important;
    position:sticky!important;
    top:78px!important;
    align-self:start!important;
    height:max-content!important;
    max-height:calc(100vh - 92px)!important;
    overflow:hidden!important;
    z-index:6!important;
  }
}

