  }
}

/* =====================================================================
   v314 — SIMPLE ORDER OPTIONS
   Compact radio-list configurator inspired by the reference mobile flow.
   ===================================================================== */
.simple-order-section{
  display:grid;
  gap:10px;
  background:#fff!important;
}
.simple-order-title{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:12px;
}
.simple-order-title>div{
  display:grid;
  gap:2px;
}
.simple-order-title small{
  font-size:8px;
  font-weight:850;
  letter-spacing:.08em;
  color:#9a7018;
}
.simple-order-title h3{
  margin:0;
  font-size:14px;
  line-height:1.35;
  color:#173f35;
}
.simple-order-title h3 span{
  color:#c84e43;
}
.simple-order-title em{
  font-style:normal;
  font-size:8px;
  color:#84918c;
}
.simple-option-list{
  display:grid;
  gap:8px;
}
.simple-option-row{
  position:relative;
  min-height:50px;
  display:grid;
  grid-template-columns:22px 1fr auto;
  align-items:center;
  gap:10px;
  padding:9px 12px;
  border:1px solid #e2e8e5;
  border-radius:10px;
  background:#f8faf9;
  cursor:pointer;
  transition:.16s ease;
}
.simple-option-row:hover{
  border-color:#a8c5b9;
  background:#f3f8f5;
}
.simple-option-row input{
  position:absolute;
  opacity:0;
  pointer-events:none;
}
.simple-radio{
  width:20px;
  height:20px;
  border:1.8px solid #bd4a43;
  border-radius:50%;
  background:#fff;
  display:grid;
  place-items:center;
}
.simple-radio::after{
  content:"";
  width:10px;
  height:10px;
  border-radius:50%;
  background:#0c674e;
  transform:scale(0);
  transition:.14s ease;
}
.simple-option-row input:checked~.simple-radio{
  border-color:#0c674e;
  box-shadow:0 0 0 3px rgba(12,103,78,.08);
}
.simple-option-row input:checked~.simple-radio::after{
  transform:scale(1);
}
.simple-option-row:has(input:checked){
  border-color:#0c674e;
  background:#edf7f2;
  box-shadow:0 5px 14px rgba(8,78,58,.06);
}
.simple-option-row b{
  font-size:11px;
  color:#243e36;
  font-weight:800;
}
